    // ========== MANAGER SCORE ==========
    // 1–10 scale: recalls, inspection sheets, stickers, housekeeping
    // v130: var (mutable) + exposed on window so the Profiles pop-up can edit it
    var managerScores = {
      "Dee": 10,
      "Daniel": 7.5,
      "Chris": 10,
      "Benji": 10,
      "Dewone": 7,
      "Nick": 5
    };
    // Apply persisted overrides (set by the Profiles pop-up) before tier calcs run
    try {
      var __mgrOv = JSON.parse(localStorage.getItem('snappy_mgr_score_overrides') || '{}');
      Object.keys(__mgrOv || {}).forEach(function(k) {
        var v = parseFloat(__mgrOv[k]);
        if (!isNaN(v)) managerScores[k] = v;
      });
    } catch (e) {}
    if (typeof window !== 'undefined') window.managerScores = managerScores;

    // ========== TIER RANKING SYSTEM ==========
    // S = Elite (92+) — maxed out / near-perfect across the board
    // A = Advanced (85–91) — strong all-around performer
    // B = Solid (78–84) — competent with room to grow
    // C = Developing (<78) — building fundamentals
    //
    // Composite score (0–100) built from:
    //   Aptitude (30%) + ST performance (35%) + Skills Tags (10%) + Manager (10%) + Installs (10%) + Reviews (5%)
    //   Skills = assigned tags / total available tags (52)

    // ========== SNAPPY SEASONS ==========
    // 4 HVAC-themed seasons per year, 3 months each. Soft reset at each boundary,
    // recalls/complaints archived, season badges + MVP auto-awarded at season end.
    const SEASON_STORAGE_KEY = 'snappy_seasons_v1';
    const SEASON_SOFT_RESET = { S: 4, A: 3, B: 1, C: 0 };

    // Season definitions — month ranges 1-indexed
    const SEASONS = [
      { key: 'ice',     name: 'Ice',     label: 'Furnace Grind',    startMonth: 1,  endMonth: 3,  emoji: '\u2744\uFE0F', color: '#7DD3FC' },
      { key: 'storm',   name: 'Storm',   label: 'Shoulder Season',  startMonth: 4,  endMonth: 6,  emoji: '\u26C8\uFE0F', color: '#A78BFA' },
      { key: 'heat',    name: 'Heat',    label: 'AC Peak',          startMonth: 7,  endMonth: 9,  emoji: '\u2600\uFE0F', color: '#FB923C' },
      { key: 'harvest', name: 'Harvest', label: 'Year-End Push',    startMonth: 10, endMonth: 12, emoji: '\ud83c\udf42', color: '#D97706' }
    ];

    function getSeasonForDate(date) {
      var m = date.getMonth() + 1; // 1-indexed
      var y = date.getFullYear();
      var s = SEASONS.find(function(s){ return m >= s.startMonth && m <= s.endMonth; });
      if (!s) s = SEASONS[0];
      return { key: s.key + '_' + y, name: s.name, label: s.label, emoji: s.emoji, color: s.color, year: y,
        startDate: new Date(y, s.startMonth - 1, 1),
        endDate: new Date(y, s.endMonth, 0, 23, 59, 59) };
    }

    function getCurrentSeason() { return getSeasonForDate(new Date()); }

    // v218: Aggregate Season-to-Date stats for a tech.
    // Sums all monthly_archive entries within the current season's month range
    // PLUS the current MTD numbers (since current month is in-progress).
    // Returns the same shape as buildStGrid expects: {nexstar, productivity, memberships, sales, label}.
    function computeSeasonToDateForTech(st) {
      var now = new Date();
      var curSeason = getCurrentSeason();
      var curYear = now.getFullYear();
      var curMonth = now.getMonth() + 1; // 1-indexed
      // Build list of YYYY-MM keys in the current season range
      var seasonDef = SEASONS.find(function(s){ return curMonth >= s.startMonth && curMonth <= s.endMonth; }) || SEASONS[0];
      var monthKeys = [];
      for (var m = seasonDef.startMonth; m <= seasonDef.endMonth; m++) {
        var mk = curYear + '-' + (m < 10 ? '0' + m : '' + m);
        monthKeys.push(mk);
      }
      var currentMonthKey = curYear + '-' + (curMonth < 10 ? '0' + curMonth : '' + curMonth);

      // Initialize accumulators
      var aggNx = { total_revenue: 0, avg_sale: 0, conversion_rate: 0, spps_sold: 0, tech_gen_leads: 0, sold_hours: 0, tech_sold_hr_eff: 0, flat_rate_tasks: 0 };
      var aggPr = { rev_hr: 0, billable_hours: 0, sold_hrs_on_job_pct: 0, tasks_per_opp: 0, options_per_opp: 0, recalls: 0 };
      var aggMb = { total_mem_sold: 0, total_mem_opps: 0, total_mem_pct: 0 };
      var aggSl = { close_rate: 0 };
      var monthsCounted = 0;
      var monthsLabels = [];

      function addMonth(srcNx, srcPr, srcMb, srcSl, label) {
        if (!srcNx) return;
        aggNx.total_revenue += (srcNx.total_revenue || 0);
        aggNx.spps_sold += (srcNx.spps_sold || 0);
        aggNx.tech_gen_leads += (srcNx.tech_gen_leads || 0);
        aggNx.sold_hours += (srcNx.sold_hours || 0);
        aggNx.flat_rate_tasks += (srcNx.flat_rate_tasks || 0);
        if (srcPr) {
          aggPr.billable_hours += (srcPr.billable_hours || 0);
          aggPr.recalls += (srcPr.recalls || 0);
        }
        if (srcMb) {
          aggMb.total_mem_sold += (srcMb.total_mem_sold || 0);
          aggMb.total_mem_opps += (srcMb.total_mem_opps || 0);
        }
        // Track rate-style fields for averaging at the end
        aggNx._convSum = (aggNx._convSum || 0) + (srcNx.conversion_rate || 0);
        aggNx._avgSaleSum = (aggNx._avgSaleSum || 0) + (srcNx.avg_sale || 0);
        if (srcPr) {
          aggPr._revHrSum = (aggPr._revHrSum || 0) + (srcPr.rev_hr || 0);
          aggPr._soldPctSum = (aggPr._soldPctSum || 0) + (srcPr.sold_hrs_on_job_pct || 0);
          aggPr._tasksPerOppSum = (aggPr._tasksPerOppSum || 0) + (srcPr.tasks_per_opp || 0);
          aggPr._optsPerOppSum = (aggPr._optsPerOppSum || 0) + (srcPr.options_per_opp || 0);
        }
        if (srcSl) {
          aggSl._closeRateSum = (aggSl._closeRateSum || 0) + (srcSl.close_rate || 0);
        }
        monthsCounted++;
        if (label) monthsLabels.push(label);
      }

      // Add archived months in season window
      monthKeys.forEach(function(mk) {
        if (mk === currentMonthKey) return; // skip current month archive (use MTD instead)
        var arch = st && st.monthly_archive && st.monthly_archive[mk];
        if (arch) {
          addMonth(arch.mtd_nexstar, arch.mtd_productivity, arch.mtd_memberships, arch.mtd_sales, arch.label || mk);
        }
      });
      // Add current month MTD
      if (st) {
        addMonth(st.mtd_nexstar || st.nexstar, st.mtd_productivity || st.productivity, st.mtd_memberships || st.memberships, st.mtd_sales || st.sales, 'Current MTD');
      }

      // Compute weighted/averaged rate fields
      var n = Math.max(1, monthsCounted);
      // Revenue-weighted conversion + avg sale where possible; fall back to simple avg
      aggNx.conversion_rate = Math.round((aggNx._convSum || 0) / n);
      aggNx.avg_sale = aggNx.spps_sold > 0
        ? Math.round(aggNx.total_revenue / Math.max(1, aggNx.spps_sold + (aggNx.flat_rate_tasks || 0)))
        : Math.round((aggNx._avgSaleSum || 0) / n);
      aggPr.rev_hr = aggPr.billable_hours > 0
        ? Math.round(aggNx.total_revenue / aggPr.billable_hours)
        : Math.round((aggPr._revHrSum || 0) / n);
      aggPr.sold_hrs_on_job_pct = Math.round((aggPr._soldPctSum || 0) / n);
      aggPr.tasks_per_opp = +(((aggPr._tasksPerOppSum || 0) / n).toFixed(2));
      aggPr.options_per_opp = +(((aggPr._optsPerOppSum || 0) / n).toFixed(2));
      aggMb.total_mem_pct = aggMb.total_mem_opps > 0 ? Math.round((aggMb.total_mem_sold / aggMb.total_mem_opps) * 100) : 0;
      aggSl.close_rate = Math.round((aggSl._closeRateSum || 0) / n);

      // Round numeric totals
      aggNx.sold_hours = +aggNx.sold_hours.toFixed(1);
      aggNx.flat_rate_tasks = +aggNx.flat_rate_tasks.toFixed(2);
      aggPr.billable_hours = +aggPr.billable_hours.toFixed(1);

      // Strip private accumulators
      delete aggNx._convSum; delete aggNx._avgSaleSum;
      delete aggPr._revHrSum; delete aggPr._soldPctSum; delete aggPr._tasksPerOppSum; delete aggPr._optsPerOppSum;
      delete aggSl._closeRateSum;

      var label = curSeason.emoji + ' ' + curSeason.name + ' ' + curYear + ' (' + monthsCounted + ' mo)';
      return { nexstar: aggNx, productivity: aggPr, memberships: aggMb, sales: aggSl, label: label, monthsCounted: monthsCounted, monthsLabels: monthsLabels, season: curSeason };
    }
    window.computeSeasonToDateForTech = computeSeasonToDateForTech;

    function getNextSeason() {
      var now = new Date();
      var cur = getSeasonForDate(now);
      var next = new Date(cur.endDate.getTime() + 24 * 60 * 60 * 1000);
      return getSeasonForDate(next);
    }

    function getSeasonDaysLeft() {
      var cur = getCurrentSeason();
      var ms = cur.endDate - new Date();
      return Math.max(0, Math.ceil(ms / (1000 * 60 * 60 * 24)));
    }

    function getSeasonTimeRemaining() {
      var cur = getCurrentSeason();
      var ms = Math.max(0, cur.endDate - new Date());
      var days = Math.floor(ms / (1000 * 60 * 60 * 24));
      var hours = Math.floor((ms / (1000 * 60 * 60)) % 24);
      var minutes = Math.floor((ms / (1000 * 60)) % 60);
      var seconds = Math.floor((ms / 1000) % 60);
      return { days: days, hours: hours, minutes: minutes, seconds: seconds, totalMs: ms };
    }

    function getSeasonProgressPct() {
      var cur = getCurrentSeason();
      var total = cur.endDate - cur.startDate;
      var elapsed = new Date() - cur.startDate;
      return Math.min(100, Math.max(0, (elapsed / total) * 100));
    }

    function loadSeasonsData() {
      try {
        var raw = localStorage.getItem(SEASON_STORAGE_KEY);
        if (raw) return JSON.parse(raw);
      } catch(e) {}
      return { currentSeason: null, transitions: [], badges: {}, mvp: {}, archivedRecalls: {}, archivedComplaints: {}, seasonStartedAt: null, pendingCeremony: null };
    }

    function saveSeasonsData(data) {
      try {
        localStorage.setItem(SEASON_STORAGE_KEY, JSON.stringify(data));
        localStorage.setItem(SEASON_STORAGE_KEY + '_localMod', String(Date.now()));
        if (typeof SyncEngine !== 'undefined' && SyncEngine.isConfigured()) SyncEngine.write('seasons', data);
      } catch(e) { console.warn('saveSeasonsData failed', e); }
    }

    // Called on app load: detect if season changed since last visit and run transition.
    function checkSeasonTransition() {
      var data = loadSeasonsData();
      var cur = getCurrentSeason();
      if (!data.currentSeason) {
        // First run ever — seed current season without reset
        data.currentSeason = cur.key;
        data.seasonStartedAt = new Date().toISOString();
        saveSeasonsData(data);
        return { transitioned: false, first: true };
      }
      if (data.currentSeason === cur.key) {
        return { transitioned: false };
      }
      // Season has changed — run transition for the OLD season
      var oldKey = data.currentSeason;
      var techSnapshots = {};
      var techsArr = (typeof techs !== 'undefined') ? techs : [];
      var tierScores = [];
      techsArr.forEach(function(t){
        try {
          var info = getTechTier(t);
          techSnapshots[t.short] = { tier: info.tier, composite: info.composite, tierLabel: info.tierLabel };
          tierScores.push({ short: t.short, composite: info.composite, tier: info.tier });
        } catch(e) {}
      });
      // Award badges (tier they finished the season in)
      if (!data.badges) data.badges = {};
      Object.keys(techSnapshots).forEach(function(short){
        if (!data.badges[short]) data.badges[short] = [];
        data.badges[short].push({ season: oldKey, tier: techSnapshots[short].tier, composite: techSnapshots[short].composite, endedAt: new Date().toISOString() });
      });
      // Pick MVP (highest composite, tiebreak alphabetical)
      tierScores.sort(function(a,b){ return b.composite - a.composite || a.short.localeCompare(b.short); });
      var mvp = tierScores[0] ? tierScores[0].short : null;
      if (!data.mvp) data.mvp = {};
      if (mvp) data.mvp[oldKey] = { tech: mvp, composite: tierScores[0].composite, tier: tierScores[0].tier };
      // Snapshot recalls + complaints for the ending season (do NOT wipe live logs)
      try {
        var recallRaw = localStorage.getItem('snappy_recall_log_v1');
        var complaintRaw = localStorage.getItem('snappy_complaint_log_v1');
        if (!data.archivedRecalls) data.archivedRecalls = {};
        if (!data.archivedComplaints) data.archivedComplaints = {};
        // Save a snapshot under the ending season key for historical reference, but keep live logs intact
        if (!data.archivedRecalls[oldKey]) data.archivedRecalls[oldKey] = recallRaw ? JSON.parse(recallRaw) : {};
        if (!data.archivedComplaints[oldKey]) data.archivedComplaints[oldKey] = complaintRaw ? JSON.parse(complaintRaw) : {};
      } catch(e) { console.warn('Snapshot logs failed', e); }
      // Record transition (including per-tech snapshot for the soft reset calculation)
      if (!data.transitions) data.transitions = [];
      data.transitions.push({ from: oldKey, to: cur.key, appliedAt: new Date().toISOString(), techSnapshots: techSnapshots, mvp: mvp });
      data.currentSeason = cur.key;
      data.seasonStartedAt = new Date().toISOString();
      // Stage ceremony for next render cycle
      data.pendingCeremony = { fromSeason: oldKey, toSeason: cur.key, mvp: mvp, snapshots: techSnapshots };
      saveSeasonsData(data);
      return { transitioned: true, fromSeason: oldKey, toSeason: cur.key, mvp: mvp, snapshots: techSnapshots };
    }

    // Soft reset penalty for current composite (applied inside getTechTier)
    function getSeasonSoftResetPenalty(techShort) {
      var data = loadSeasonsData();
      if (!data.transitions || !data.transitions.length) return 0;
      var last = data.transitions[data.transitions.length - 1];
      if (!last || last.to !== getCurrentSeason().key) return 0;
      var snap = last.techSnapshots && last.techSnapshots[techShort];
      if (!snap) return 0;
      return SEASON_SOFT_RESET[snap.tier] || 0;
    }

    function getTechSeasonBadges(techShort) {
      var data = loadSeasonsData();
      return (data.badges && data.badges[techShort]) || [];
    }

    function getSeasonDisplayName(seasonKey) {
      if (!seasonKey) return '';
      var parts = seasonKey.split('_');
      var name = parts[0];
      var year = parts[1];
      var s = SEASONS.find(function(x){ return x.key === name; });
      return s ? (s.emoji + ' ' + s.name + ' ' + year) : seasonKey;
    }

    // Expose for debug + rookie card + UI
    window.getCurrentSeason = getCurrentSeason;
    window.getSeasonDaysLeft = getSeasonDaysLeft;
    window.getSeasonProgressPct = getSeasonProgressPct;
    window.checkSeasonTransition = checkSeasonTransition;
    window.getSeasonSoftResetPenalty = getSeasonSoftResetPenalty;
    window.getTechSeasonBadges = getTechSeasonBadges;
    window.getSeasonDisplayName = getSeasonDisplayName;
    window.loadSeasonsData = loadSeasonsData;
    window.saveSeasonsData = saveSeasonsData;

    // ========== SEASON BANNER ==========
    function renderSeasonBanner() {
      var el = document.getElementById('seasonBanner');
      if (!el) return;
      try {
        var cur = getCurrentSeason();
        var days = getSeasonDaysLeft();
        var pct = getSeasonProgressPct();
        var next = getNextSeason();
        var countdownLabel = days === 0 ? 'Ends today' : (days === 1 ? '1 day left' : days + ' days left');
        var isStorm = cur.key.indexOf('storm_') === 0;
        el.style.display = 'flex';
        el.style.background = 'linear-gradient(90deg, ' + cur.color + '2E 0%, ' + cur.color + '10 100%)';
        el.style.borderColor = cur.color + '80';
        var boltSvg = '<svg viewBox="0 0 24 36" fill="currentColor"><path d="M14 0 L2 20 L10 20 L6 36 L22 14 L14 14 Z"/></svg>';
        var stormTitle = isStorm
          ? 'STORM ' + cur.year + ' &middot; SUMMER RAMP UP <span class="storm-ramp-chip">\u26A1 Ramp Up</span>'
          : cur.name + ' ' + cur.year + ' &middot; ' + cur.label;
        var stormSub = isStorm
          ? 'AC systems firing up &middot; Storm demand surge &middot; Next up: ' + next.emoji + ' ' + next.name
          : 'Next up: ' + next.emoji + ' ' + next.name;
        var t = getSeasonTimeRemaining();
        var countdownHTML =
          '<div class="sb-countdown-deluxe" style="--sb-color:' + cur.color + '">' +
            '<div class="sb-cd-label">\u26A1 Season Ends In</div>' +
            '<div class="sb-cd-units">' +
              '<div class="sb-cd-unit"><div class="sb-cd-num" data-unit="days">' + String(t.days).padStart(2,"0") + '</div><div class="sb-cd-ulbl">DAYS</div></div>' +
              '<span class="sb-cd-sep">:</span>' +
              '<div class="sb-cd-unit"><div class="sb-cd-num" data-unit="hours">' + String(t.hours).padStart(2,"0") + '</div><div class="sb-cd-ulbl">HRS</div></div>' +
              '<span class="sb-cd-sep">:</span>' +
              '<div class="sb-cd-unit"><div class="sb-cd-num" data-unit="minutes">' + String(t.minutes).padStart(2,"0") + '</div><div class="sb-cd-ulbl">MIN</div></div>' +
              '<span class="sb-cd-sep">:</span>' +
              '<div class="sb-cd-unit"><div class="sb-cd-num sb-cd-secs" data-unit="seconds">' + String(t.seconds).padStart(2,"0") + '</div><div class="sb-cd-ulbl">SEC</div></div>' +
            '</div>' +
          '</div>';
        el.innerHTML =
          (isStorm ? '<span class="storm-banner-bolt left">' + boltSvg + '</span>' : '') +
          '<span class="sb-emoji">' + cur.emoji + '</span>' +
          '<div class="sb-main">' +
            '<div class="sb-title">' + stormTitle + '</div>' +
            '<div class="sb-sub">' + stormSub + '</div>' +
            '<div class="sb-progress"><div class="sb-progress-fill" style="width:' + pct.toFixed(1) + '%;background:' + cur.color + '"></div></div>' +
          '</div>' +
          countdownHTML +
          (isStorm ? '<span class="storm-banner-bolt right">' + boltSvg + '</span>' : '');
        // Start live ticker
        _startCountdownTicker();
        // Toggle the global storm FX layer + body class
        applyStormFX(isStorm);
      } catch(e) { console.warn('renderSeasonBanner failed', e); }
    }
    window.renderSeasonBanner = renderSeasonBanner;

    // Live per-second countdown ticker — updates only the numbers in place
    var _countdownTickerInterval = null;
    function _startCountdownTicker() {
      if (_countdownTickerInterval) return;
      _countdownTickerInterval = setInterval(function() {
        try {
          var el = document.getElementById('seasonBanner');
          if (!el || el.style.display === 'none') return;
          var t = getSeasonTimeRemaining();
          var nums = el.querySelectorAll('.sb-cd-num');
          nums.forEach(function(n) {
            var unit = n.getAttribute('data-unit');
            var val = String(t[unit]).padStart(2, '0');
            if (n.textContent !== val) {
              n.textContent = val;
              // Flicker animation on change
              n.classList.remove('sb-cd-flip');
              void n.offsetWidth;
              n.classList.add('sb-cd-flip');
            }
          });
        } catch(e) {}
      }, 1000);
    }
    window.getSeasonTimeRemaining = getSeasonTimeRemaining;

    // ========== STORM SEASON FX ==========
    var _stormFxState = { active: false, lightningTimer: null };

    function _generateStormBoltPath() {
      // Build a jagged top-to-bottom bolt with 5-7 segments
      var startX = 200 + Math.random() * 1520;
      var y = 0;
      var path = 'M ' + startX + ' ' + y;
      var segments = 5 + Math.floor(Math.random() * 3);
      var segLen = 1080 / segments;
      var x = startX;
      for (var i = 0; i < segments; i++) {
        y += segLen;
        x += (Math.random() - 0.5) * 220;
        path += ' L ' + x.toFixed(0) + ' ' + y.toFixed(0);
        // Occasional fork
        if (Math.random() < 0.35 && i < segments - 1) {
          var forkX = x + (Math.random() - 0.5) * 180;
          var forkY = y + segLen * (0.3 + Math.random() * 0.5);
          path += ' M ' + x.toFixed(0) + ' ' + y.toFixed(0) + ' L ' + forkX.toFixed(0) + ' ' + forkY.toFixed(0) + ' M ' + x.toFixed(0) + ' ' + y.toFixed(0);
        }
      }
      return path;
    }

    function _triggerLightning() {
      var flash = document.getElementById('stormFlash');
      var svg = document.getElementById('stormBoltOverlay');
      if (!flash || !svg) return;
      // Flash
      flash.classList.remove('storm-flash-strike');
      void flash.offsetWidth;
      flash.classList.add('storm-flash-strike');
      // Bolt
      var d = _generateStormBoltPath();
      // Remove any existing bolts
      var existing = svg.querySelectorAll('.storm-bolt-path');
      existing.forEach(function(p){ p.remove(); });
      var glow = document.createElementNS('http://www.w3.org/2000/svg', 'path');
      glow.setAttribute('d', d);
      glow.setAttribute('class', 'storm-bolt-path storm-bolt-glow-bg storm-bolt-strike');
      var bolt = document.createElementNS('http://www.w3.org/2000/svg', 'path');
      bolt.setAttribute('d', d);
      bolt.setAttribute('class', 'storm-bolt-path storm-bolt-strike');
      svg.appendChild(glow);
      svg.appendChild(bolt);
      // Optional distant thunder cue via subtle camera shake
      try {
        var c = document.querySelector('.container');
        if (c) {
          c.style.transition = 'transform 0.08s';
          c.style.transform = 'translate(1px, -1px)';
          setTimeout(function(){ c.style.transform = 'translate(-1px, 1px)'; }, 80);
          setTimeout(function(){ c.style.transform = ''; }, 160);
        }
      } catch(e){}
      // Cleanup bolt after animation
      setTimeout(function(){
        glow.remove();
        bolt.remove();
      }, 1200);
    }

    function _scheduleNextLightning() {
      if (!_stormFxState.active) return;
      var reduced = false;
      try { reduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch(e){}
      if (reduced) return;
      // Random 8-22s between strikes
      var delay = 8000 + Math.random() * 14000;
      _stormFxState.lightningTimer = setTimeout(function(){
        if (!_stormFxState.active) return;
        _triggerLightning();
        // Sometimes a quick double strike
        if (Math.random() < 0.3) {
          setTimeout(_triggerLightning, 400 + Math.random() * 600);
        }
        _scheduleNextLightning();
      }, delay);
    }

    // Canvas rain particles
    var _rainState = { canvas: null, ctx: null, drops: [], rafId: null };

    function _startRainCanvas() {
      var container = document.getElementById('stormRain');
      if (!container) return;
      container.innerHTML = '';
      var canvas = document.createElement('canvas');
      var dpr = window.devicePixelRatio || 1;
      function resize() {
        var w = window.innerWidth;
        var h = window.innerHeight;
        canvas.width = w * dpr;
        canvas.height = h * dpr;
        canvas.style.width = w + 'px';
        canvas.style.height = h + 'px';
      }
      resize();
      container.appendChild(canvas);
      var ctx = canvas.getContext('2d');
      ctx.scale(dpr, dpr);
      _rainState.canvas = canvas;
      _rainState.ctx = ctx;

      // Initialize drops — density scales with viewport
      var area = window.innerWidth * window.innerHeight;
      var targetCount = Math.min(520, Math.max(180, Math.floor(area / 3600)));
      _rainState.drops = [];
      for (var i = 0; i < targetCount; i++) {
        _rainState.drops.push(_makeDrop(true));
      }

      window.addEventListener('resize', _onRainResize);

      function loop() {
        if (!_stormFxState.active) return;
        _tickRain();
        _rainState.rafId = requestAnimationFrame(loop);
      }
      loop();
    }
    function _onRainResize() {
      if (!_rainState.canvas) return;
      var dpr = window.devicePixelRatio || 1;
      var w = window.innerWidth, h = window.innerHeight;
      _rainState.canvas.width = w * dpr;
      _rainState.canvas.height = h * dpr;
      _rainState.canvas.style.width = w + 'px';
      _rainState.canvas.style.height = h + 'px';
      _rainState.ctx.setTransform(1, 0, 0, 1, 0, 0);
      _rainState.ctx.scale(dpr, dpr);
    }

    function _makeDrop(initial) {
      var w = window.innerWidth, h = window.innerHeight;
      // Depth: 0=near (bigger/faster/brighter), 1=far (smaller/slower/fainter)
      var depth = Math.random();
      var speed = 11 + (1 - depth) * 14 + Math.random() * 4; // 11-29 px/frame @ 60fps
      // Shorter streaks so drops read as drops not stripes — longer only for near drops
      var length = 4 + (1 - depth) * (1 - depth) * 10 + Math.random() * 3; // 4-17 px
      var opacity = 0.22 + (1 - depth) * 0.55;
      var thickness = 0.6 + (1 - depth) * 1.2;
      // Wind varies slightly per-drop so streaks don't perfectly align
      var wind = -1.4 - (1 - depth) * 1.3 + (Math.random() - 0.5) * 0.6;
      // Color mix: mostly soft violet with occasional cyan and white
      var r = Math.random();
      var hue = r < 0.18 ? 'cyan' : (r < 0.26 ? 'white' : 'purple');
      return {
        x: Math.random() * (w + 120) - 60,
        y: initial ? Math.random() * h : -length - Math.random() * 80,
        vx: wind,
        vy: speed / 2.2,
        len: length,
        op: opacity,
        th: thickness,
        hue: hue,
        splash: 0
      };
    }

    function _tickRain() {
      var ctx = _rainState.ctx;
      var w = window.innerWidth, h = window.innerHeight;
      ctx.clearRect(0, 0, w, h);
      ctx.globalCompositeOperation = 'lighter'; // glow-additive for water highlight feel
      var drops = _rainState.drops;
      for (var i = 0; i < drops.length; i++) {
        var d = drops[i];
        // Tail: start faint at top, brighten at head (where the drop really is)
        var tailX = d.x - d.vx * (d.len / Math.max(Math.abs(d.vy), 0.1));
        var tailY = d.y - d.len;
        var grad = ctx.createLinearGradient(tailX, tailY, d.x, d.y);
        var col = d.hue === 'cyan' ? '125,211,252' : (d.hue === 'white' ? '226,232,240' : '167,139,250');
        grad.addColorStop(0, 'rgba(' + col + ',0)');
        grad.addColorStop(0.6, 'rgba(' + col + ',' + (d.op * 0.35) + ')');
        grad.addColorStop(1, 'rgba(' + col + ',' + d.op + ')');
        ctx.strokeStyle = grad;
        ctx.lineWidth = d.th;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(tailX, tailY);
        ctx.lineTo(d.x, d.y);
        ctx.stroke();
        // Bright head dot — makes it read as a water droplet, not a line
        ctx.fillStyle = 'rgba(' + col + ',' + Math.min(1, d.op * 1.2) + ')';
        ctx.beginPath();
        ctx.arc(d.x, d.y, d.th * 0.9, 0, Math.PI * 2);
        ctx.fill();
        // Advance
        d.x += d.vx;
        d.y += d.vy;
        if (d.y > h + d.len || d.x < -80) {
          drops[i] = _makeDrop(false);
          drops[i].x = Math.random() * (w + 120) - 40;
        }
      }
      ctx.globalCompositeOperation = 'source-over';
    }

    function _stopRainCanvas() {
      if (_rainState.rafId) cancelAnimationFrame(_rainState.rafId);
      _rainState.rafId = null;
      var container = document.getElementById('stormRain');
      if (container) container.innerHTML = '';
      _rainState.drops = [];
      _rainState.canvas = null;
      _rainState.ctx = null;
      window.removeEventListener('resize', _onRainResize);
    }

    function applyStormFX(enable) {
      if (enable === _stormFxState.active) return;
      _stormFxState.active = !!enable;
      var layer = document.getElementById('stormFxLayer');
      var reduced = false;
      try { reduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch(e){}
      if (enable) {
        document.body.classList.add('storm-season');
        if (layer) layer.style.display = 'block';
        if (!reduced) _startRainCanvas();
        // Kick off an opening strike after 1.5s, then schedule
        setTimeout(function(){
          if (_stormFxState.active) _triggerLightning();
        }, 1500);
        _scheduleNextLightning();
      } else {
        document.body.classList.remove('storm-season');
        if (layer) layer.style.display = 'none';
        _stopRainCanvas();
        if (_stormFxState.lightningTimer) {
          clearTimeout(_stormFxState.lightningTimer);
          _stormFxState.lightningTimer = null;
        }
      }
    }
    window.applyStormFX = applyStormFX;
    window._triggerLightning = _triggerLightning; // expose for debug

    // ========== MVP CEREMONY MODAL ==========
    function _confettiBurst(durationMs) {
      var colors = ['#fbbf24','#A78BFA','#60a5fa','#34d399','#f472b6','#fb923c','#7DD3FC'];
      var count = 80;
      for (var i = 0; i < count; i++) {
        (function(idx){
          setTimeout(function(){
            var p = document.createElement('div');
            p.className = 'confetti-piece';
            p.style.left = Math.random() * 100 + 'vw';
            p.style.background = colors[Math.floor(Math.random()*colors.length)];
            var dur = 2800 + Math.random() * 2200;
            p.style.animationDuration = dur + 'ms';
            p.style.width = (6 + Math.random()*6) + 'px';
            p.style.height = (10 + Math.random()*10) + 'px';
            p.style.transform = 'rotate(' + (Math.random()*360) + 'deg)';
            document.body.appendChild(p);
            setTimeout(function(){ if (p.parentNode) p.parentNode.removeChild(p); }, dur + 200);
          }, idx * 30);
        })(i);
      }
    }

    function showMVPCeremony() {
      try {
        var data = loadSeasonsData();
        if (!data || !data.pendingCeremony) return;
        var ceremony = data.pendingCeremony;
        var fromName = getSeasonDisplayName(ceremony.fromSeason);
        var toName = getSeasonDisplayName(ceremony.toSeason);
        var mvpShort = ceremony.mvp;
        var mvpTech = null;
        try { mvpTech = (typeof techs !== 'undefined') ? techs.find(function(t){ return t.short === mvpShort; }) : null; } catch(e){}
        var mvpName = mvpTech ? mvpTech.name : (mvpShort || 'Unknown');
        var mvpScore = (data.mvp && data.mvp[ceremony.fromSeason] && data.mvp[ceremony.fromSeason].composite) || 0;
        var mvpTier = (data.mvp && data.mvp[ceremony.fromSeason] && data.mvp[ceremony.fromSeason].tier) || 'A';

        var rosterRows = '';
        var snapshots = ceremony.snapshots || {};
        Object.keys(snapshots).sort(function(a,b){ return snapshots[b].composite - snapshots[a].composite; }).forEach(function(short){
          var s = snapshots[short];
          var tierColor = s.tier === 'S' ? '#fbbf24' : s.tier === 'A' ? '#60a5fa' : s.tier === 'B' ? '#34d399' : '#9ca3af';
          rosterRows += '<div class="mvp-roster-row">' +
            '<span class="mvp-roster-name">' + short + (short === mvpShort ? ' \u{1F451}' : '') + '</span>' +
            '<span class="mvp-roster-tier" style="background:' + tierColor + '33;color:' + tierColor + ';border:1px solid ' + tierColor + '">' + s.tier + '-TIER &middot; ' + (s.composite||0).toFixed(1) + '</span>' +
          '</div>';
        });

        var overlay = document.createElement('div');
        overlay.className = 'mvp-ceremony-overlay';
        overlay.id = 'mvpCeremonyOverlay';
        overlay.innerHTML =
          '<div class="mvp-ceremony-box">' +
            '<h2>Season Complete</h2>' +
            '<div class="mvp-season-line">' + fromName + ' \u2192 ' + toName + '</div>' +
            '<div class="mvp-trophy">\u{1F3C6}</div>' +
            '<div class="mvp-title">SEASON MVP</div>' +
            '<div class="mvp-name">' + mvpName + '</div>' +
            '<div class="mvp-score">' + mvpTier + '-Tier &middot; ' + (mvpScore||0).toFixed(1) + ' composite</div>' +
            '<div class="mvp-roster">' + rosterRows + '</div>' +
            '<div class="mvp-next-up">A light soft-reset has been applied based on last season\'s finish. Recall &amp; complaint logs are archived. Badges are locked in. Fresh start for ' + toName + '.</div>' +
            '<button class="mvp-dismiss" id="mvpDismissBtn">Start ' + toName.replace(/^\S+\s/, '') + '</button>' +
          '</div>';
        document.body.appendChild(overlay);
        _confettiBurst(3000);
        var dismiss = function() {
          var d = loadSeasonsData();
          d.pendingCeremony = null;
          saveSeasonsData(d);
          overlay.remove();
        };
        document.getElementById('mvpDismissBtn').addEventListener('click', dismiss);
        overlay.addEventListener('click', function(e){ if (e.target === overlay) dismiss(); });
      } catch(e) { console.warn('showMVPCeremony failed', e); }
    }
    window.showMVPCeremony = showMVPCeremony;
    // ========== SEASON BADGE UNIVERSE + SEASONS SUB-TAB ==========
    // Renders:
    //   1. #seasonBadgeUniverse  — all 16 possible badges (4 seasons x 4 tiers) + MVP
    //   2. #seasonHeroCard       — current season hero card
    //   3. #compositeExplainer   — composite score weights + tier thresholds
    //   4. #rookieGridSeasonal   — season-themed rookie cards (re-skin of rookie cards)
    //   5. #earnedBadgesGallery  — per-tech earned badges
    // Requires getCurrentSeason, SEASONS, loadSeasonsData, getTechTier, techs, getSeasonDisplayName

    // Helper — season metadata by key
    function _getAllSeasons() {
      try { return (typeof SEASONS !== 'undefined') ? SEASONS : []; }
      catch(e) { return []; }
    }

    function _monthRangeLabel(s) {
      var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
      return months[s.startMonth - 1] + '-' + months[s.endMonth - 1];
    }

    // ---------- 1. Badge Universe (on overview, below team photo) ----------
    // v143: collapsed by default — shows only the current season + total earned count.
    // Click "View all seasons" to expand the full 4-season grid.
    var SBU_EXPANDED_KEY = 'snappy_sbu_expanded';
    function _sbuIsExpanded() {
      try { return localStorage.getItem(SBU_EXPANDED_KEY) === '1'; } catch(e) { return false; }
    }
    function _sbuSetExpanded(v) {
      try { localStorage.setItem(SBU_EXPANDED_KEY, v ? '1' : '0'); } catch(e) {}
    }
    function renderSeasonBadgeUniverse() {
      var el = document.getElementById('seasonBadgeUniverse');
      if (!el) return;
      try {
        var seasons = _getAllSeasons();
        if (!seasons.length) { el.style.display = 'none'; return; }
        var cur = (typeof getCurrentSeason === 'function') ? getCurrentSeason() : null;
        var curName = cur ? cur.name : '';
        var expanded = _sbuIsExpanded();

        // Count total earned badges across all techs/seasons
        var earnedCount = 0;
        var totalPossible = seasons.length * 4 + seasons.length; // 4 tier badges + 1 MVP per season
        try {
          var data = (typeof loadSeasonsData === 'function') ? loadSeasonsData() : null;
          if (data && data.badges) {
            Object.keys(data.badges).forEach(function(k) {
              earnedCount += (data.badges[k] || []).length;
            });
          }
        } catch(e) {}

        var tiers = [
          { key: 'S', label: 'Elite',    color: '#FFD700', desc: '92+' },
          { key: 'A', label: 'Advanced', color: '#EF4444', desc: '85-91' },
          { key: 'B', label: 'Solid',    color: '#60A5FA', desc: '78-84' },
          { key: 'C', label: 'Rising',   color: '#94A3B8', desc: '<78' }
        ];

        function badgeHTML(s, t) {
          return '<div class="sbu-badge tier-' + t.key.toLowerCase() + '" title="' + s.name + ' \u2014 ' + t.key + '-Tier (' + t.label + ')">' +
            '<div class="sbu-badge-tier">' + t.key + '</div>' +
            '<div class="sbu-badge-emoji">' + s.emoji + '</div>' +
            '<div class="sbu-badge-season-label">' + s.name + '</div>' +
          '</div>';
        }

        // ---------- COLLAPSED MODE ----------
        if (!expanded) {
          var curSeason = seasons.filter(function(s) { return s.name === curName; })[0] || seasons[0];
          var curBadgesHTML = tiers.map(function(t) { return badgeHTML(curSeason, t); }).join('');

          el.classList.add('sbu-compact');
          el.innerHTML =
            '<div class="sbu-compact-head">' +
              '<div class="sbu-compact-title-block">' +
                '<span class="sbu-compact-emoji">' + curSeason.emoji + '</span>' +
                '<div class="sbu-compact-text">' +
                  '<div class="sbu-compact-title">Season Badges \u2014 ' + curSeason.name + ' ' + curSeason.year + '</div>' +
                  '<div class="sbu-compact-sub">' + earnedCount + ' / ' + totalPossible + ' badges collected this year</div>' +
                '</div>' +
              '</div>' +
              '<button type="button" class="sbu-toggle" id="sbu-toggle">View all seasons \u2192</button>' +
            '</div>' +
            '<div class="sbu-compact-row">' + curBadgesHTML + '</div>';

          var btn = document.getElementById('sbu-toggle');
          if (btn) btn.onclick = function() { _sbuSetExpanded(true); renderSeasonBadgeUniverse(); };
          return;
        }

        // ---------- EXPANDED MODE (legacy full grid) ----------
        el.classList.remove('sbu-compact');
        var legendHTML = tiers.map(function(t) {
          return '<span class="sbu-legend-item"><span class="sbu-legend-dot" style="background:' + t.color + ';color:' + t.color + '"></span>' + t.key + '-TIER &middot; ' + t.label + '</span>';
        }).join('');

        var seasonsHTML = seasons.map(function(s) {
          var isCurrent = (s.name === curName);
          var badgesHTML = tiers.map(function(t) { return badgeHTML(s, t); }).join('');
          return '<div class="sbu-season-col' + (isCurrent ? ' current' : '') + '">' +
            '<div class="sbu-season-head">' +
              '<span class="sbu-season-emoji">' + s.emoji + '</span>' +
              '<span class="sbu-season-name">' + s.name + (isCurrent ? ' \u2605' : '') + '</span>' +
              '<span class="sbu-season-months">' + _monthRangeLabel(s) + '</span>' +
            '</div>' +
            '<div class="sbu-season-label">' + s.label + '</div>' +
            '<div class="sbu-badges-row">' + badgesHTML + '</div>' +
          '</div>';
        }).join('');

        el.innerHTML =
          '<div class="sbu-head">' +
            '<span class="sbu-title">\ud83c\udfc6 Season Badge Universe</span>' +
            '<button type="button" class="sbu-toggle" id="sbu-toggle">\u2190 Collapse</button>' +
          '</div>' +
          '<div class="sbu-subtitle">Finish a season in tier &rarr; claim the badge forever</div>' +
          '<div class="sbu-legend">' + legendHTML + '</div>' +
          '<div class="sbu-seasons-grid">' + seasonsHTML + '</div>' +
          '<div class="sbu-mvp-row">' +
            '<span class="sbu-mvp-trophy">\ud83c\udfc6</span>' +
            '<div class="sbu-mvp-text">' +
              '<div class="sbu-mvp-title">Season MVP Badge \u2014 1 per season</div>' +
              '<div class="sbu-mvp-desc">Awarded to the highest composite score when a season ends. Only one per three months \u2014 the most coveted collectible.</div>' +
            '</div>' +
          '</div>';
        var btn2 = document.getElementById('sbu-toggle');
        if (btn2) btn2.onclick = function() { _sbuSetExpanded(false); renderSeasonBadgeUniverse(); };
      } catch(e) { console.warn('renderSeasonBadgeUniverse failed', e); }
    }
    window.renderSeasonBadgeUniverse = renderSeasonBadgeUniverse;

