      try { renderSeasonBadgeUniverse(); } catch(e) {}
      try { renderSeasonHeroCard(); } catch(e) {}
      try { renderCompositeExplainer(); } catch(e) {}
      try { renderSeasonSelector(); } catch(e) {}
