    // ========== SKILLS PERSISTENCE (localStorage) ==========
    const SKILLS_STORAGE_KEY = 'snappy_skills_assignments';
    const DEFAULT_ASSIGNMENTS = JSON.parse(JSON.stringify(skillsData.assignments));

    // Load saved assignments from localStorage on init
    (function loadSavedAssignments() {
      try {
        const saved = localStorage.getItem(SKILLS_STORAGE_KEY);
        if (saved) {
          const parsed = JSON.parse(saved);
          // v176: Migrate — add any missing tech keys (e.g., Nick) from defaults
          let migrated = false;
          Object.keys(DEFAULT_ASSIGNMENTS).forEach(function(k) {
            if (!parsed[k]) { parsed[k] = DEFAULT_ASSIGNMENTS[k].slice(); migrated = true; }
          });
          // Validate structure: must have same tech keys (after migration)
          const defaultKeys = Object.keys(DEFAULT_ASSIGNMENTS).sort().join(',');
          const savedKeys = Object.keys(parsed).sort().join(',');
          if (defaultKeys === savedKeys) {
            skillsData.assignments = parsed;
            if (migrated) {
              try { localStorage.setItem(SKILLS_STORAGE_KEY, JSON.stringify(parsed)); } catch(e) {}
            }
          }
        }
      } catch (e) { /* ignore parse errors, use defaults */ }
    })();

    function saveSkillAssignments() {
      try {
        localStorage.setItem(SKILLS_STORAGE_KEY, JSON.stringify(skillsData.assignments));
        if (SyncEngine.isConfigured()) SyncEngine.write('skills', skillsData.assignments);
        // Flash save indicator
        const indicator = document.getElementById('skSaveIndicator');
        if (indicator) {
          indicator.classList.add('show');
          clearTimeout(indicator._hideTimer);
          indicator._hideTimer = setTimeout(() => indicator.classList.remove('show'), 1800);
        }
      } catch (e) { /* localStorage full or unavailable */ }
    }

    // ========== SKILL UNLOCK LOG (localStorage + SyncEngine) ==========
    // Writes a history entry every time a skill is newly checked off for a tech.
    // Stored as array of { tech, skillId, skillName, cat, ts } newest-first.
    const SKILL_LOG_KEY = 'snappy_skill_log_v1';
    const SKILL_LOG_MAX = 200; // hard cap on history length
    function skillLogLoad() {
      try {
        const raw = localStorage.getItem(SKILL_LOG_KEY);
        if (!raw) return [];
        const parsed = JSON.parse(raw);
        return Array.isArray(parsed) ? parsed : [];
      } catch (e) { return []; }
    }
    function skillLogSave(arr) {
      try {
        const trimmed = arr.slice(0, SKILL_LOG_MAX);
        localStorage.setItem(SKILL_LOG_KEY, JSON.stringify(trimmed));
        try { localStorage.setItem(SKILL_LOG_KEY + '_localMod', Date.now().toString()); } catch(e) {}
        if (typeof SyncEngine !== 'undefined' && SyncEngine.isConfigured()) {
          try { SyncEngine.write('skilllog', trimmed); } catch(e) {}
        }
      } catch (e) { /* quota */ }
    }
    function skillLogLookup(skillId) {
      // Returns { name, cat, color } for a given skill id, or {} if not found.
      const cats = skillsData.categories || {};
      for (const k in cats) {
        const match = (cats[k].skills || []).find(s => s.id === skillId);
        if (match) return { name: match.name, cat: k, color: cats[k].color };
      }
      return { name: skillId, cat: '', color: '#64748b' };
    }
    function logSkillUnlock(tech, skillId) {
      const info = skillLogLookup(skillId);
      const entry = {
        tech: tech,
        skillId: skillId,
        skillName: info.name,
        cat: info.cat,
        ts: Date.now()
      };
      const arr = skillLogLoad();
      arr.unshift(entry);
      skillLogSave(arr);
    }
    function getRecentSkillUnlocks(limit, forTech) {
      const arr = skillLogLoad();
      const filtered = forTech ? arr.filter(e => e.tech === forTech) : arr;
      return filtered.slice(0, limit || 20);
    }
    function fmtSkillLogTime(ts) {
      if (!ts) return '';
      const now = Date.now();
      const diff = Math.max(0, now - ts);
      const mins = Math.floor(diff / 60000);
      if (mins < 1) return 'just now';
      if (mins < 60) return mins + 'm ago';
      const hrs = Math.floor(mins / 60);
      if (hrs < 24) return hrs + 'h ago';
      const days = Math.floor(hrs / 24);
      if (days < 7) return days + 'd ago';
      const d = new Date(ts);
      return (d.getMonth() + 1) + '/' + d.getDate();
    }
    // Expose for cross-module access
    window.SkillLog = {
      log: logSkillUnlock,
      recent: getRecentSkillUnlocks,
      fmtTime: fmtSkillLogTime,
      lookup: skillLogLookup
    };

    function toggleSkill(tech, skillId) {
      if (!requireManager()) return;
      const arr = skillsData.assignments[tech];
      const idx = arr.indexOf(skillId);
      if (idx >= 0) {
        arr.splice(idx, 1); // remove
      } else {
        arr.push(skillId); // add
        arr.sort(); // keep sorted by ID
        // Log newly-earned skill to history (only on add, never on remove)
        try { logSkillUnlock(tech, skillId); } catch(e) { console.warn('logSkillUnlock failed:', e); }
      }
      saveSkillAssignments();
      renderSkillsTags(); // re-render all sub-tabs reactively
      // Live-refresh profiles, overview, and rookie cards since skills affect composite
      try { renderProfiles(); } catch(e) {}
      try { renderOverviewTab(); } catch(e) {}
      try { renderRookieCards(); } catch(e) {}

      // Apply pop animation to the toggled cell
      setTimeout(() => {
        const cell = document.querySelector(`[data-skill-toggle="${tech}-${skillId}"]`);
        if (cell) {
          cell.classList.add('just-toggled');
          setTimeout(() => cell.classList.remove('just-toggled'), 350);
        }
      }, 10);
    }

    function resetSkillEdits() {
      if (!confirm('Reset all skill assignments to original defaults? This cannot be undone.')) return;
      skillsData.assignments = JSON.parse(JSON.stringify(DEFAULT_ASSIGNMENTS));
      localStorage.removeItem(SKILLS_STORAGE_KEY);
      renderSkillsTags();
    }

    // ========== TAB NAVIGATION ==========
    // KPI card click navigation
    window.navigateToKpi = function(tabView, stSub) {
      // Switch main tab
      var mainTab = document.querySelector('.nav-tab[data-view="' + tabView + '"]');
      if (mainTab) {
        document.querySelectorAll('.nav-tabs:not(#st-sub-tabs):not(#as-sub-tabs):not(#sk-sub-tabs):not(#mgr-sub-tabs) .nav-tab').forEach(function(t) { t.classList.remove('active'); });
        document.querySelectorAll('.view-section').forEach(function(s) { s.classList.remove('active'); });
        mainTab.classList.add('active');
        document.getElementById('view-' + tabView).classList.add('active');
      }
      // If ST sub-tab specified, switch to it
      if (stSub && tabView === 'scorecards') {
        var stTab = document.querySelector('#st-sub-tabs .nav-tab[data-st="' + stSub + '"]');
        if (stTab) {
          document.querySelectorAll('#st-sub-tabs .nav-tab').forEach(function(t) { t.classList.remove('active'); });
          document.querySelectorAll('.st-section').forEach(function(s) { s.classList.remove('active'); });
          stTab.classList.add('active');
          var stSection = document.getElementById('st-' + stSub);
          if (stSection) stSection.classList.add('active');
        }
      }
      // Close sidebar if open (mobile slide-in or desktop expanded)
      if (window.innerWidth <= 768) {
        var navEl = document.querySelector('.nav-tabs');
        if (navEl) navEl.classList.remove('mobile-open');
      } else {
        document.body.classList.remove('sidebar-expanded');
        localStorage.setItem('sidebarExpanded', 'false');
      }
      // Scroll to top
      window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    document.querySelectorAll('.nav-tabs:not(#st-sub-tabs):not(#as-sub-tabs):not(#sk-sub-tabs):not(#mgr-sub-tabs) .nav-tab').forEach(tab => {
      tab.addEventListener('click', () => {
        document.querySelectorAll('.nav-tabs:not(#st-sub-tabs):not(#as-sub-tabs):not(#sk-sub-tabs):not(#mgr-sub-tabs) .nav-tab').forEach(t => t.classList.remove('active'));
        document.querySelectorAll('.view-section').forEach(s => s.classList.remove('active'));
        tab.classList.add('active');
        document.getElementById('view-' + tab.dataset.view).classList.add('active');
        // Always scroll to top on tab switch
        window.scrollTo({ top: 0, behavior: 'instant' });
        // Close mobile sidebar on nav
        if (window.innerWidth < 769) {
          document.querySelector('.nav-tabs').classList.remove('mobile-open');
        }
        // Auto-mark NEW skills as seen when visiting skills-related tabs
        var v = tab.dataset.view;
        if (v === 'skills-tags' || v === 'aptitude-skills' || v === 'overview') {
          _markNewSkillsSeen();
        }
        // Animate counters when switching to overview
        if (v === 'overview') { setTimeout(animateCounters, 300); }
        // v202: Re-render Overview tab content (incl. MTD KPI tiles) when switching back.
        // Previously only renderBulletinBoard() ran here, so the MTD tiles
        // (Service Revenue, MTD Installs, Install Revenue, etc.) showed stale numbers
        // until a full page reload after data updates.
        if (v === 'overview') {
          try { renderOverviewTab(); } catch(e) { console.warn('renderOverviewTab on tab switch failed:', e); }
          renderBulletinBoard();
          if (!radar3dRendered) {
            setTimeout(renderRadar, 200);
          }
        }
        // v202: Re-render Scorecards KPI row + tables on every visit so MTD tiles stay live.
        if (v === 'scorecards') {
          try { renderSTKPIs(); } catch(e) { console.warn('renderSTKPIs on tab switch failed:', e); }
          try { renderSTTables(); } catch(e) { console.warn('renderSTTables on tab switch failed:', e); }
        }
        // v217: Sales Team scorecard
        if (v === 'sales') {
          try { if (typeof renderSalesScorecard === 'function') renderSalesScorecard(); } catch(e) { console.warn('renderSalesScorecard on tab switch failed:', e); }
        }
        // v218.4: Install Pay tracker (PIN-locked, local-only)
        if (v === 'installpay') {
          try {
            if (typeof ipIsUnlocked === 'function' && !ipIsUnlocked()) {
              if (typeof ipPromptPin === 'function') ipPromptPin();
            } else if (typeof renderInstallPay === 'function') {
              renderInstallPay();
            }
          } catch(e) { console.warn('renderInstallPay on tab switch failed:', e); }
        }
        // v202: Re-render Manager content when entering manager tab.
        if (v === 'manager') {
          try { if (typeof renderMgrToday === 'function') renderMgrToday(); } catch(e) {}
        }
        // Re-render rookie cards when switching to rookie tab — picks up latest recalls/complaints from dispatch
        if (v === 'rookie') {
          try { renderRookieCards(); } catch(e) { console.warn('renderRookieCards on tab switch failed:', e); }
          // Also refresh seasonal views if the Seasons sub-tab is active
          try {
            var active = document.querySelector('#view-rookie .rookie-subnav-btn.active');
            if (active && active.dataset.subview === 'seasons') renderSeasonsHub();
          } catch(e) {}
        }
      });
    });

    function _markNewSkillsSeen() {
      setTimeout(function() {
        var newIds = [];
        Object.keys(skillsData.categories).forEach(function(k) {
          skillsData.categories[k].skills.forEach(function(s) {
            if (s.isNew) newIds.push(s.id);
          });
        });
        if (newIds.length) {
          markSkillsSeen(newIds);
          // Re-render to remove badges
          renderSkillsTags();
        }
      }, 2000);
    }

    // Aptitude & Skills sub-tabs
    document.querySelectorAll('#as-sub-tabs .nav-tab').forEach(tab => {
      tab.addEventListener('click', () => {
        document.querySelectorAll('#as-sub-tabs .nav-tab').forEach(t => t.classList.remove('active'));
        document.querySelectorAll('.as-section').forEach(s => s.classList.remove('active'));
        tab.classList.add('active');
        document.getElementById('as-' + tab.dataset.as).classList.add('active');
      });
    });

    // ========== PHASE 3: ANIMATED COUNTER ==========
    function animateCounters() {
      document.querySelectorAll('.ov-kpi-value, .kpi-value').forEach(function(el) {
        var textNode = null;
        for (var i = 0; i < el.childNodes.length; i++) {
          if (el.childNodes[i].nodeType === Node.TEXT_NODE) {
            textNode = el.childNodes[i];
            break;
          }
        }
        if (!textNode) return;
        var text = textNode.nodeValue.trim();
        var prefix = '';
        var numStr = text;
        if (text.startsWith('$')) { prefix = '$'; numStr = text.slice(1); }
        numStr = numStr.replace(/,/g, '');
        var target = parseFloat(numStr);
        if (isNaN(target)) return;
        var isFloat = numStr.includes('.');
        var duration = 800;
        var start = performance.now();
        var startVal = 0;
        function tick(now) {
          var elapsed = now - start;
          var progress = Math.min(elapsed / duration, 1);
          var eased = 1 - Math.pow(1 - progress, 3);
          var current = startVal + (target - startVal) * eased;
          if (isFloat) {
            textNode.nodeValue = prefix + current.toFixed(1);
          } else {
            textNode.nodeValue = prefix + Math.round(current).toLocaleString();
          }
          if (progress < 1) requestAnimationFrame(tick);
        }
        requestAnimationFrame(tick);
      });
    }
    // Trigger counters when Overview tab is shown
    var origSwitchView = null;
    document.addEventListener('DOMContentLoaded', function() {
      setTimeout(animateCounters, 500);
      setTimeout(initTeamPhoto, 200);
    });

    // ========== TEAM PHOTO — seasonal toggle + animated storm FX ==========
    var TEAM_PHOTO_KEY = 'snappy_team_photo_mode';
    var _teamRain = { canvas: null, ctx: null, drops: [], rafId: null, ro: null };
    var _teamLightningTimer = null;

    function initTeamPhoto() {
      var card = document.getElementById('teamPhotoCard');
      if (!card) return;
      var buttons = card.querySelectorAll('.team-toggle-btn');
      // Decide initial mode: stored preference wins; otherwise default to current season (Storm if storm season active)
      var stored = null;
      try { stored = localStorage.getItem(TEAM_PHOTO_KEY); } catch(e){}
      var season = (typeof _stormFxState !== 'undefined' && _stormFxState.active) ? 'storm' : 'original';
      var mode = stored === 'original' || stored === 'storm' ? stored : season;
      _setTeamPhotoMode(mode);

      buttons.forEach(function(btn){
        btn.addEventListener('click', function(){
          var m = btn.getAttribute('data-mode');
          _setTeamPhotoMode(m);
          try { localStorage.setItem(TEAM_PHOTO_KEY, m); } catch(e){}
        });
      });
    }

    function _setTeamPhotoMode(mode) {
      var card = document.getElementById('teamPhotoCard');
      if (!card) return;
      card.setAttribute('data-mode', mode);
      var buttons = card.querySelectorAll('.team-toggle-btn');
      buttons.forEach(function(b){
        var active = b.getAttribute('data-mode') === mode;
        b.classList.toggle('active', active);
        b.setAttribute('aria-selected', active ? 'true' : 'false');
      });
      var reduced = false;
      try { reduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch(e){}
      if (mode === 'storm' && !reduced) {
        _startTeamRain();
        _scheduleTeamLightning();
      } else {
        _stopTeamRain();
        if (_teamLightningTimer) { clearTimeout(_teamLightningTimer); _teamLightningTimer = null; }
      }
    }

    function _startTeamRain() {
      var canvas = document.querySelector('#teamPhotoCard .team-rain-canvas');
      if (!canvas) return;
      var ctx = canvas.getContext('2d');
      _teamRain.canvas = canvas;
      _teamRain.ctx = ctx;

      function resize() {
        var rect = canvas.getBoundingClientRect();
        var dpr = window.devicePixelRatio || 1;
        canvas.width = Math.max(1, Math.floor(rect.width * dpr));
        canvas.height = Math.max(1, Math.floor(rect.height * dpr));
        ctx.setTransform(1,0,0,1,0,0);
        ctx.scale(dpr, dpr);
        _teamRain._cssW = rect.width;
        _teamRain._cssH = rect.height;
        // Re-seed drops at new size
        var area = rect.width * rect.height;
        var count = Math.min(260, Math.max(70, Math.floor(area / 2400)));
        _teamRain.drops = [];
        for (var i = 0; i < count; i++) _teamRain.drops.push(_makeTeamDrop(true));
      }
      resize();

      // Handle container resize (toggling view, window resize)
      if (_teamRain.ro) _teamRain.ro.disconnect();
      if (typeof ResizeObserver !== 'undefined') {
        _teamRain.ro = new ResizeObserver(function(){ resize(); });
        _teamRain.ro.observe(canvas);
      }

      function loop() {
        var card = document.getElementById('teamPhotoCard');
        if (!card || card.getAttribute('data-mode') !== 'storm') return;
        _tickTeamRain();
        _teamRain.rafId = requestAnimationFrame(loop);
      }
      if (_teamRain.rafId) cancelAnimationFrame(_teamRain.rafId);
      loop();
    }

    function _makeTeamDrop(initial) {
      var w = _teamRain._cssW || 800;
      var h = _teamRain._cssH || 450;
      var depth = Math.random();
      var speed = 9 + (1 - depth) * 12 + Math.random() * 3;
      var length = 3 + (1 - depth) * (1 - depth) * 9 + Math.random() * 2;
      var opacity = 0.28 + (1 - depth) * 0.6;
      var thickness = 0.55 + (1 - depth) * 1.1;
      var wind = -1.1 - (1 - depth) * 1.1 + (Math.random() - 0.5) * 0.5;
      var r = Math.random();
      var hue = r < 0.22 ? 'cyan' : (r < 0.30 ? 'white' : 'purple');
      return {
        x: Math.random() * (w + 100) - 50,
        y: initial ? Math.random() * h : -length - Math.random() * 60,
        vx: wind,
        vy: speed / 2.2,
        len: length,
        op: opacity,
        th: thickness,
        hue: hue
      };
    }

    function _tickTeamRain() {
      var ctx = _teamRain.ctx;
      var w = _teamRain._cssW, h = _teamRain._cssH;
      if (!ctx || !w || !h) return;
      ctx.clearRect(0, 0, w, h);
      ctx.globalCompositeOperation = 'lighter';
      var drops = _teamRain.drops;
      for (var i = 0; i < drops.length; i++) {
        var d = drops[i];
        var tailX = d.x - d.vx * (d.len / Math.max(Math.abs(d.vy), 0.1));
        var tailY = d.y - d.len;
        var grad = ctx.createLinearGradient(tailX, tailY, d.x, d.y);
        var col = d.hue === 'cyan' ? '125,211,252' : (d.hue === 'white' ? '226,232,240' : '196,181,253');
        grad.addColorStop(0, 'rgba(' + col + ',0)');
        grad.addColorStop(0.6, 'rgba(' + col + ',' + (d.op * 0.35) + ')');
        grad.addColorStop(1, 'rgba(' + col + ',' + d.op + ')');
        ctx.strokeStyle = grad;
        ctx.lineWidth = d.th;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(tailX, tailY);
        ctx.lineTo(d.x, d.y);
        ctx.stroke();
        ctx.fillStyle = 'rgba(' + col + ',' + Math.min(1, d.op * 1.2) + ')';
        ctx.beginPath();
        ctx.arc(d.x, d.y, d.th * 0.9, 0, Math.PI * 2);
        ctx.fill();
        d.x += d.vx;
        d.y += d.vy;
        if (d.y > h + d.len || d.x < -80) {
          drops[i] = _makeTeamDrop(false);
          drops[i].x = Math.random() * (w + 120) - 40;
        }
      }
      ctx.globalCompositeOperation = 'source-over';
    }

    function _stopTeamRain() {
      if (_teamRain.rafId) cancelAnimationFrame(_teamRain.rafId);
      _teamRain.rafId = null;
      if (_teamRain.ro) { _teamRain.ro.disconnect(); _teamRain.ro = null; }
      if (_teamRain.ctx && _teamRain._cssW) {
        _teamRain.ctx.clearRect(0, 0, _teamRain._cssW, _teamRain._cssH);
      }
      _teamRain.drops = [];
    }

    function _scheduleTeamLightning() {
      if (_teamLightningTimer) clearTimeout(_teamLightningTimer);
      var delay = 3500 + Math.random() * 6500; // 3.5 - 10s between flashes
      _teamLightningTimer = setTimeout(function(){
        var card = document.getElementById('teamPhotoCard');
        if (!card || card.getAttribute('data-mode') !== 'storm') return;
        _triggerTeamLightning();
        _scheduleTeamLightning();
      }, delay);
    }

    function _triggerTeamLightning() {
      var flash = document.querySelector('#teamPhotoCard .team-lightning-flash');
      if (!flash) return;
      flash.classList.remove('team-flash-on');
      // Force reflow so animation restarts
      void flash.offsetWidth;
      flash.classList.add('team-flash-on');
    }

    // ========== RENDER KPIs ==========
    function renderKPIs() {
      const teamAvg = techs.reduce((s,t) => s + techOverallAvg(t), 0) / techs.length;
      const strongest = Object.keys(categories).reduce((best, cat) =>
        teamCategoryAvg(cat) > teamCategoryAvg(best) ? cat : best
      );
      const weakest = Object.keys(categories).reduce((worst, cat) =>
        teamCategoryAvg(cat) < teamCategoryAvg(worst) ? cat : worst
      );
      const topTech = techs.reduce((best, t) => techOverallAvg(t) > techOverallAvg(best) ? t : best);
      const totalYears = techs.reduce((s,t) => s + t.years, 0);

      document.getElementById('kpi-row').innerHTML = `
        <div class="kpi-card">
          <div class="kpi-label">Team Average</div>
          <div class="kpi-value" style="color:var(--accent-teal)">${teamAvg.toFixed(1)}<span style="font-size:14px;color:var(--text-muted);font-weight:400"> / 5</span></div>
          <div class="kpi-sub">Across all skill categories</div>
        </div>
        <div class="kpi-card">
          <div class="kpi-label">Strongest Area</div>
          <div class="kpi-value" style="font-size:18px;">${categories[strongest].label}</div>
          <div class="kpi-sub">Avg ${teamCategoryAvg(strongest).toFixed(1)}</div>
        </div>
        <div class="kpi-card">
          <div class="kpi-label">Needs Focus</div>
          <div class="kpi-value" style="font-size:18px;color:var(--accent-red)">${categories[weakest].label}</div>
          <div class="kpi-sub">Avg ${teamCategoryAvg(weakest).toFixed(1)}</div>
        </div>
        <div class="kpi-card">
          <div class="kpi-label">Top Scorer</div>
          <div class="kpi-value" style="font-size:18px;">${topTech.short}</div>
          <div class="kpi-sub">Avg ${techOverallAvg(topTech).toFixed(1)} — ${topTech.years} yrs</div>
        </div>
        <div class="kpi-card">
          <div class="kpi-label">Combined Experience</div>
          <div class="kpi-value">${totalYears}<span style="font-size:14px;color:var(--text-muted);font-weight:400"> yrs</span></div>
          <div class="kpi-sub">Avg ${(totalYears/techs.length).toFixed(0)} years per tech</div>
        </div>
      `;
    }

    // ========== OVERVIEW TAB ==========
    const BB_KEY = 'snappy_bulletin_board';

    function bbLoad() {
      try {
        var d = JSON.parse(localStorage.getItem(BB_KEY)) || {};
        return { meetings: d.meetings || [], oneOnOnes: d.oneOnOnes || [], rideAlongs: d.rideAlongs || [], matrixUpdates: d.matrixUpdates || [] };
      } catch(e) { return { meetings: [], oneOnOnes: [], rideAlongs: [], matrixUpdates: [] }; }
    }
    function bbSave(data) {
      localStorage.setItem(BB_KEY, JSON.stringify(data));
      localStorage.setItem(BB_KEY + '_localMod', String(Date.now()));
      if (SyncEngine.isConfigured()) SyncEngine.write('bulletin', data);
      // Re-render tech profiles so Coaching History stays in sync with BB
      try { if (typeof renderProfiles === 'function') renderProfiles(); } catch(e) {}
    }
    function bbUID() {
      return Date.now().toString(36) + Math.random().toString(36).substr(2, 6);
    }

    // v196: Unified coaching-history loader.
    // Returns ALL saved 1-on-1 + ride-along entries from BOTH the Bulletin Board
    // (snappy_bulletin_board) AND the Manager calendar (snappy_manager_entries),
    // deduped by id. Preferring richer mgrState data when both exist.
    // Earlier (v194/v195) the viewers only read the Bulletin Board, so any entry
    // saved in the Manager tab without "Add to Bulletin Board" was invisible
    // even though Coaching History counts/last-dates appeared correct in some cases.
    function _chNormTech(s) { return String(s == null ? '' : s).trim().toLowerCase(); }
    function _chTechOf(entry) {
      if (!entry) return '';
      // Support legacy / alt schemas (technician, name, displayName, person)
      return entry.tech || entry.technician || entry.techName || entry.name || entry.displayName || entry.person || '';
    }
    function _chLoadAllEntries() {
      var bb = bbLoad();
      var bbOO = Array.isArray(bb.oneOnOnes) ? bb.oneOnOnes : [];
      var bbRA = Array.isArray(bb.rideAlongs) ? bb.rideAlongs : [];

      // Pull mgrState entries from in-memory if available, else from localStorage.
      var mgrEntries = [];
      try {
        if (typeof mgrState !== 'undefined' && mgrState && Array.isArray(mgrState.entries)) {
          mgrEntries = mgrState.entries;
        } else {
          var rawM = localStorage.getItem('snappy_manager_entries');
          if (rawM) {
            var parsedM = JSON.parse(rawM) || {};
            if (Array.isArray(parsedM.entries)) mgrEntries = parsedM.entries;
          }
        }
      } catch(_) {}

      var mgrById = {};
      mgrEntries.forEach(function(e) { if (e && e.id) mgrById[e.id] = e; });

      var seen = {};
      var combined = [];

      function pushUnified(src, kind) {
        if (!src || !src.id) {
          // Synthesize an id so duplicates within a single source still merge by date+tech.
          var key = kind + '|' + (_chTechOf(src) || '?') + '|' + (src && src.date || '') + '|' + (src && src.time || '');
          if (seen[key]) return;
          seen[key] = true;
        } else {
          if (seen[src.id]) return;
          seen[src.id] = true;
        }
        var rich = src.id ? mgrById[src.id] : null;
        // src may already BE a mgr entry, in which case rich === src — that's fine.
        var data = (rich && rich.data) ? rich.data : (src.data || null);
        combined.push({
          id: src.id || ('synth_' + combined.length),
          kind: kind,
          tech: _chTechOf(src) || (rich ? _chTechOf(rich) : ''),
          date: src.date || (rich && rich.date) || '',
          time: src.time || (rich && rich.time) || '',
          status: src.status || (rich && rich.status) || 'planned',
          notes: src.notes || (rich && rich.data && (rich.data.customFocus || rich.data.observationNotes)) || '',
          data: data,
          updatedAt: (rich && rich.updatedAt) || src.updatedAt || null,
          createdAt: (rich && rich.createdAt) || src.createdAt || null,
          source: src.source || (rich && !src.tech ? 'mgr' : 'bb')
        });
      }

      bbOO.forEach(function(o) { pushUnified(o, 'one-on-one'); });
      bbRA.forEach(function(r) { pushUnified(r, 'ride-along'); });
      // Pull mgrState-only entries (those never promoted to the Bulletin Board)
      mgrEntries.forEach(function(e) {
        if (!e || !e.type) return;
        if (e.type === 'one-on-one' || e.type === '1on1' || e.type === 'oneonone' || e.type === 'one_on_one') {
          pushUnified(e, 'one-on-one');
        } else if (e.type === 'ride-along' || e.type === 'ridealong' || e.type === 'ride_along') {
          pushUnified(e, 'ride-along');
        }
      });
      return combined;
    }
    function _chFilterTech(entries, tech) {
      if (!tech) return entries.slice();
      var t = _chNormTech(tech);
      return entries.filter(function(e) { return _chNormTech(e.tech) === t; });
    }
    // Expose for debugging / shared use
    window._chLoadAllEntries = _chLoadAllEntries;

    // v194/v196: Coaching History detail modal — opened from clickable pills on Profile cards
    // type: 'one-on-one' | 'ride-along' | 'all'
    function openCoachingHistoryDetail(tech, type) {
      try {
        var all = _chLoadAllEntries();
        var forTech = _chFilterTech(all, tech);
        var ooList = forTech.filter(function(e) { return e.kind === 'one-on-one'; })
          .sort(function(a,b) { return (b.date||'').localeCompare(a.date||''); });
        var raList = forTech.filter(function(e) { return e.kind === 'ride-along'; })
          .sort(function(a,b) { return (b.date||'').localeCompare(a.date||''); });

        var showOO = (type === 'one-on-one' || type === 'all');
        var showRA = (type === 'ride-along' || type === 'all');

        var titleLabel = type === 'one-on-one' ? '1-on-1 History'
                       : type === 'ride-along' ? 'Ride-Along History'
                       : 'Coaching History';
        var accent = type === 'ride-along' ? '#10B981' : '#3B82F6';
        var accentBg = type === 'ride-along' ? 'rgba(16,185,129,0.15)' : 'rgba(59,130,246,0.15)';

        // Remove any existing modal
        var existing = document.getElementById('coachHistoryModal');
        if (existing) existing.remove();

        var bodyHtml = '';
        if (showOO) {
          bodyHtml += '<div class="ch-detail-section">';
          bodyHtml += '<div class="ch-detail-section-title oneonone">🤝 1-on-1 Sessions <span class="ch-detail-count">' + ooList.length + '</span></div>';
          if (ooList.length === 0) {
            bodyHtml += '<div class="ch-detail-empty">No 1-on-1s recorded for ' + escHtml(tech) + ' yet.</div>';
          } else {
            ooList.forEach(function(e) { bodyHtml += renderCoachHistoryEntry(e); });
          }
          bodyHtml += '</div>';
        }
        if (showRA) {
          bodyHtml += '<div class="ch-detail-section">';
          bodyHtml += '<div class="ch-detail-section-title ridealong">🚐 Ride-Alongs <span class="ch-detail-count">' + raList.length + '</span></div>';
          if (raList.length === 0) {
            bodyHtml += '<div class="ch-detail-empty">No ride-alongs recorded for ' + escHtml(tech) + ' yet.</div>';
          } else {
            raList.forEach(function(e) { bodyHtml += renderCoachHistoryEntry(e); });
          }
          bodyHtml += '</div>';
        }

        var modal = document.createElement('div');
        modal.id = 'coachHistoryModal';
        modal.className = 'log-entry-modal-overlay coach-history-modal-overlay';
        modal.innerHTML =
          '<div class="log-entry-modal coach-history-modal" style="border-top:4px solid ' + accent + '">' +
            '<div class="log-entry-modal-header">' +
              '<div class="log-entry-modal-title">' +
                '<span class="log-entry-modal-badge" style="background:' + accentBg + ';color:' + accent + '">' + escHtml(titleLabel) + '</span>' +
                '<span>' + escHtml(tech) + '</span>' +
              '</div>' +
              '<button class="log-entry-modal-close" id="coachHistModalClose" aria-label="Close">&times;</button>' +
            '</div>' +
            '<div class="log-entry-modal-body coach-history-modal-body">' + bodyHtml + '</div>' +
          '</div>';
        document.body.appendChild(modal);

        var close = function() { var m = document.getElementById('coachHistoryModal'); if (m) m.remove(); document.removeEventListener('keydown', onKey); };
        var onKey = function(e) { if (e.key === 'Escape') close(); };
        modal.addEventListener('click', function(e) { if (e.target === modal) close(); });
        var btn = document.getElementById('coachHistModalClose');
        if (btn) btn.addEventListener('click', close);
        document.addEventListener('keydown', onKey);
      } catch(err) {
        try { console.error('openCoachingHistoryDetail failed', err); } catch(_) {}
      }
    }
    window.openCoachingHistoryDetail = openCoachingHistoryDetail;

    function renderCoachHistoryEntry(e) {
      var statusClass = 'status-' + (e.status || 'planned');
      var html = '<div class="ch-entry">';
      html += '<div class="ch-entry-head">';
      html += '<div class="ch-entry-head-left">';
      html += '<span class="ch-entry-date">' + escHtml(e.date || 'No date') + '</span>';
      if (e.time) html += '<span class="ch-entry-time">' + escHtml(e.time) + '</span>';
      html += '</div>';
      html += '<span class="coach-log-status ' + statusClass + '">' + escHtml(e.status || 'planned') + '</span>';
      html += '</div>';

      var d = e.data || {};
      var anyDetail = false;

      if (e.kind === 'ride-along') {
        // Call type pill
        if (d.callType) {
          var ctLabel = d.callType === 'maintenance' ? 'Maintenance Call' : (d.callType === 'demand' ? 'Demand / Service Call' : (d.callType === 'soldWork' ? 'Sold Work / Repair' : d.callType));
          var ctColor = d.callType === 'maintenance' ? '#0EA5E9' : (d.callType === 'demand' ? '#F59E0B' : (d.callType === 'soldWork' ? '#10B981' : '#64748b'));
          html += '<div class="ch-entry-row"><span class="ch-entry-label">Call Type</span><span class="ch-entry-tag" style="background:' + ctColor + '22;color:' + ctColor + ';border:1px solid ' + ctColor + '55">' + escHtml(ctLabel) + '</span></div>';
          anyDetail = true;
        }
        if (d.custIssue) { html += renderChField('Customer Issue / Symptom', d.custIssue); anyDetail = true; }
        if (d.actualDiagnosis) { html += renderChField('Actual Diagnosis / Root Cause', d.actualDiagnosis); anyDetail = true; }
        if (d.repairPerformed) { html += renderChField('Repair Performed / Options Presented', d.repairPerformed); anyDetail = true; }
        if (d.callOutcome) { html += renderChField('Outcome', d.callOutcome); anyDetail = true; }

        // Maintenance flow detail
        if (d.callType === 'maintenance' && d.maintenance) {
          var m = d.maintenance;
          var maintChecks = collectChecks(m, [
            ['hk_arrival', 'On-time arrival'],
            ['hk_uniform', 'Uniform / appearance'],
            ['hk_floor', 'Floor / shoe protection'],
            ['intro_greet', 'Customer greet & intro'],
            ['filter_check', 'Filter check / replace'],
            ['coil_clean', 'Coil cleaning / inspection'],
            ['drain_clear', 'Condensate / drain check'],
            ['amps_measured', 'Amp draws measured'],
            ['pressures_measured', 'Refrigerant pressures'],
            ['delta_t', 'ΔT supply/return'],
            ['safeties_tested', 'Safeties tested'],
            ['photos_uploaded', 'Photos uploaded'],
            ['rec_membership', 'Membership / maintenance plan offered'],
            ['rec_repair', 'Repair recommendation made'],
            ['rec_replace', 'Replacement option presented']
          ]);
          if (maintChecks.length) { html += renderChChecks('Maintenance Checks', maintChecks); anyDetail = true; }
          if (m.findings) { html += renderChField('Findings', m.findings); anyDetail = true; }
          if (m.recommendations) { html += renderChField('Recommendations', m.recommendations); anyDetail = true; }
          if (m.notes) { html += renderChField('Maintenance Notes', m.notes); anyDetail = true; }
        }

        // Demand flow detail
        if (d.callType === 'demand' && d.demand) {
          var dem = d.demand;
          if (dem.symptom) { html += renderChField('Symptom (customer’s words)', dem.symptom); anyDetail = true; }
          if (dem.onset) { html += renderChField('Onset', dem.onset); anyDetail = true; }
          if (dem.history) { html += renderChField('System History', dem.history); anyDetail = true; }
          if (dem.expectations) { html += renderChField('Customer Expectations', dem.expectations); anyDetail = true; }
          var diagChecks = collectChecks(dem, [
            ['diag_visual', 'Visual inspection'],
            ['diag_thermostat', 'Thermostat & call-for'],
            ['diag_voltage', 'Line / control voltage'],
            ['diag_amp', 'Amp draws'],
            ['diag_pressures', 'Refrigerant pressures'],
            ['diag_temps', 'Supply / return temps & ΔT'],
            ['diag_capacitor', 'Capacitor under load'],
            ['diag_safeties', 'Safety circuits / floats'],
            ['diag_airflow', 'Airflow / static pressure']
          ]);
          if (diagChecks.length) { html += renderChChecks('Diagnostic Steps', diagChecks); anyDetail = true; }
          if (dem.diagSteps) { html += renderChField('Diagnostic Walkthrough', dem.diagSteps); anyDetail = true; }
          if (dem.rootCause) { html += renderChField('Root Cause', dem.rootCause); anyDetail = true; }
          if (dem.contributing) { html += renderChField('Contributing Factors', dem.contributing); anyDetail = true; }
          if (dem.explained) { html += renderChField('How Explained to Customer', dem.explained); anyDetail = true; }
          var optChecks = collectChecks(dem, [
            ['opt_repair', 'Repair option'],
            ['opt_replace_component', 'Component replacement'],
            ['opt_replace_system', 'System replacement'],
            ['opt_membership', 'Membership offered'],
            ['opt_financing', 'Financing presented']
          ]);
          if (optChecks.length) { html += renderChChecks('Options Presented', optChecks); anyDetail = true; }
          if (dem.options) { html += renderChField('Good / Better / Best', dem.options); anyDetail = true; }
          if (dem.decision) { html += renderChField('Customer Decision', dem.decision); anyDetail = true; }
          var postChecks = collectChecks(dem, [
            ['post_cycle', 'Cycle-tested heat & cool'],
            ['post_pressures', 'Pressures / SH / SC re-verified'],
            ['post_temps', 'ΔT confirmed in spec'],
            ['post_amps', 'Amp draws re-measured'],
            ['post_safeties', 'Safeties confirmed'],
            ['post_walkthrough', 'Walkthrough with customer'],
            ['post_photos', 'Before / after photos'],
            ['post_review', 'Review / referral asked']
          ]);
          if (postChecks.length) { html += renderChChecks('Post-Repair Verification', postChecks); anyDetail = true; }
          if (dem.postReadings) { html += renderChField('Post-Repair Readings', dem.postReadings); anyDetail = true; }
          if (dem.leftIn) { html += renderChField('System Left In', dem.leftIn); anyDetail = true; }
        }

        // Sold Work / Repair flow detail
        if (d.callType === 'soldWork' && d.soldWork) {
          var sw = d.soldWork;
          if (sw.scope) { html += renderChField('Scope of Work Sold', sw.scope); anyDetail = true; }
          if (sw.soldBy) { html += renderChField('Sold By', sw.soldBy); anyDetail = true; }
          if (sw.amount) { html += renderChField('Sold Amount', sw.amount); anyDetail = true; }
          if (sw.history) { html += renderChField('System History', sw.history); anyDetail = true; }
          if (sw.expectations) { html += renderChField('Customer Expectations', sw.expectations); anyDetail = true; }
          var preChecks = collectChecks(sw, [
            ['pre_invoice_reviewed', 'Sold invoice / scope reviewed'],
            ['pre_parts_loaded', 'Parts & materials loaded / staged'],
            ['pre_customer_confirm', 'Scope confirmed with customer'],
            ['pre_floor_protect', 'Floor / shoe protection'],
            ['pre_power_off', 'Power / disconnect off & locked'],
            ['pre_baseline_readings', 'Baseline readings recorded'],
            ['pre_photos', 'Before photos uploaded'],
            ['pre_safety_ppe', 'PPE / safety gear in place']
          ]);
          if (preChecks.length) { html += renderChChecks('Pre-Work Verification', preChecks); anyDetail = true; }
          if (sw.baselineReadings) { html += renderChField('Baseline Readings', sw.baselineReadings); anyDetail = true; }
          var execChecks = collectChecks(sw, [
            ['exec_followed_scope', 'Followed sold scope exactly'],
            ['exec_used_correct_parts', 'Used correct parts / materials'],
            ['exec_brazing', 'Brazing / nitrogen purge (if applicable)'],
            ['exec_evac', 'Evacuation pulled (if applicable)'],
            ['exec_charged', 'System charged to spec'],
            ['exec_torqued', 'Connections torqued / leak-checked'],
            ['exec_workspace_clean', 'Workspace kept clean during job']
          ]);
          if (execChecks.length) { html += renderChChecks('Repair Execution', execChecks); anyDetail = true; }
          if (sw.walkthrough) { html += renderChField('Execution Walkthrough', sw.walkthrough); anyDetail = true; }
          if (sw.issues) { html += renderChField('Issues / Surprises', sw.issues); anyDetail = true; }
          if (sw.partsUsed) { html += renderChField('Parts Used', sw.partsUsed); anyDetail = true; }
          if (sw.laborHours) { html += renderChField('Labor Hours', sw.laborHours); anyDetail = true; }
          if (sw.addlFindings) { html += renderChField('Additional Findings', sw.addlFindings); anyDetail = true; }
          if (sw.addOns) { html += renderChField('Add-Ons Sold On Job', sw.addOns); anyDetail = true; }
          var qcChecks = collectChecks(sw, [
            ['qc_cycle', 'Cycle-tested heat & cool'],
            ['qc_pressures', 'Pressures / SH / SC verified'],
            ['qc_temps', 'ΔT confirmed in spec'],
            ['qc_amps', 'Amp draws verified'],
            ['qc_safeties', 'Safeties confirmed'],
            ['qc_leak_check', 'Leak check passed'],
            ['qc_thermostat', 'Thermostat / controls verified'],
            ['qc_no_callbacks', 'No callback risk identified'],
            ['qc_warranty_logged', 'Warranty / job notes logged']
          ]);
          if (qcChecks.length) { html += renderChChecks('Quality Check / Post-Work', qcChecks); anyDetail = true; }
          if (sw.postReadings) { html += renderChField('Post-Work Readings', sw.postReadings); anyDetail = true; }
          var closeChecks = collectChecks(sw, [
            ['close_walkthrough', 'Walkthrough with customer'],
            ['close_after_photos', 'After photos uploaded'],
            ['close_warranty_explained', 'Warranty explained to customer'],
            ['close_membership_offered', 'Membership offered'],
            ['close_invoice_signed', 'Invoice presented & signed'],
            ['close_payment_collected', 'Payment / financing finalized'],
            ['close_review', 'Review / referral asked'],
            ['close_jobsite_clean', 'Jobsite cleaner than we found it']
          ]);
          if (closeChecks.length) { html += renderChChecks('Customer Closeout', closeChecks); anyDetail = true; }
          if (sw.satisfaction) { html += renderChField('Customer Satisfaction Read', sw.satisfaction); anyDetail = true; }
          if (sw.followUp) { html += renderChField('Follow-Up Needed', sw.followUp); anyDetail = true; }
          if (sw.leftIn) { html += renderChField('System Left In', sw.leftIn); anyDetail = true; }
        }

        if (d.debriefManagerBetter) { html += renderChField('Debrief — Manager: What could be better', d.debriefManagerBetter); anyDetail = true; }
        if (d.debriefTechBetter) { html += renderChField('Debrief — Tech: What could be better', d.debriefTechBetter); anyDetail = true; }
        if (d.debriefManagerWin) { html += renderChField('Debrief — Manager: What a WIN looks like', d.debriefManagerWin); anyDetail = true; }
        if (d.debriefTechWin) { html += renderChField('Debrief — Tech: What a WIN looks like', d.debriefTechWin); anyDetail = true; }

        if (d.observationNotes) { html += renderChField('Observation Notes', d.observationNotes); anyDetail = true; }
        if (d.nextSteps) { html += renderChField('Next Steps', d.nextSteps); anyDetail = true; }
        if (d.nssGreetScores && d.nssGreetScores.total) {
          html += '<div class="ch-entry-row"><span class="ch-entry-label">NSS Greet Score</span><span class="ch-entry-tag">' + escHtml(String(d.nssGreetScores.total)) + ' / 100</span></div>';
          anyDetail = true;
        }
      } else if (e.kind === 'one-on-one') {
        if (d.customFocus) { html += renderChField('Focus / Topic', d.customFocus); anyDetail = true; }
        if (d.coveredSummary) { html += renderChField('What Was Covered', d.coveredSummary); anyDetail = true; }
        if (d.actionItems) { html += renderChField('Action Items', d.actionItems); anyDetail = true; }
        if (d.followUp) { html += renderChField('Follow-Up', d.followUp); anyDetail = true; }
        if (d.redBarn && d.redBarn.include) {
          if (d.redBarn.scenario) { html += renderChField('Red Barn — Scenario', d.redBarn.scenario); anyDetail = true; }
          if (d.redBarn.outcome) { html += renderChField('Red Barn — Outcome', d.redBarn.outcome); anyDetail = true; }
        }
        if (d.housekeepingNotes) { html += renderChField('Housekeeping Notes', d.housekeepingNotes); anyDetail = true; }
      }

      // Generic notes (from BB) — always show if present and not duplicated
      if (e.notes && (!d || (d.customFocus !== e.notes && d.observationNotes !== e.notes))) {
        html += renderChField('Notes', e.notes);
        anyDetail = true;
      }
      if (d && d.rescheduleReason) { html += renderChField('Reschedule Reason', d.rescheduleReason); anyDetail = true; }

      if (!anyDetail) {
        html += '<div class="ch-entry-empty">No additional details saved for this entry.</div>';
      }
      html += '</div>';
      return html;
    }

    function renderChField(label, value) {
      return '<div class="ch-entry-field"><div class="ch-entry-label">' + escHtml(label) + '</div><div class="ch-entry-value">' + escHtml(String(value)).replace(/\n/g, '<br>') + '</div></div>';
    }

    function renderChChecks(label, items) {
      var html = '<div class="ch-entry-field"><div class="ch-entry-label">' + escHtml(label) + '</div><div class="ch-entry-checks">';
      items.forEach(function(it) {
        html += '<span class="ch-check-pill"><span class="ch-check-tick">✓</span>' + escHtml(it) + '</span>';
      });
      html += '</div></div>';
      return html;
    }

    function collectChecks(obj, defs) {
      var out = [];
      if (!obj) return out;
      defs.forEach(function(pair) { if (obj[pair[0]]) out.push(pair[1]); });
      return out;
    }

