    // Show/hide maintenance vs demand vs soldWork sections based on selected Call Type
    function mgrToggleCallTypeSections() {
      const sel = document.querySelector('#mgrRideAlongForm input[name="r_callType"]:checked');
      const val = sel ? sel.value : '';
      const maintEl = document.getElementById('r_maintenanceSections');
      const demandEl = document.getElementById('r_demandSections');
      const soldEl = document.getElementById('r_soldWorkSections');
      if (maintEl) maintEl.style.display = (val === 'maintenance') ? '' : 'none';
      if (demandEl) demandEl.style.display = (val === 'demand') ? '' : 'none';
      if (soldEl) soldEl.style.display = (val === 'soldWork') ? '' : 'none';
    }

    function mgrWireNssGreetStars() {
      const section = document.getElementById('r_nssGreetSection');
      if (!section) return;
      section.querySelectorAll('.mgr-nss-stars').forEach(row => {
        row.querySelectorAll('.mgr-nss-star').forEach(btn => {
          btn.addEventListener('click', () => {
            const star = parseInt(btn.getAttribute('data-nss-star'), 10);
            const current = parseInt(row.getAttribute('data-nss-value') || '0', 10);
            const next = (star === current) ? 0 : star;
            row.setAttribute('data-nss-value', String(next));
            row.querySelectorAll('.mgr-nss-star').forEach(s => {
              const n = parseInt(s.getAttribute('data-nss-star'), 10);
              s.classList.toggle('filled', n <= next);
            });
            const valEl = row.querySelector('.mgr-nss-val');
            if (valEl) valEl.textContent = next || '\u2014';
            mgrRecalcNssGreetTotals();
          });
        });
      });
    }

    function mgrRecalcNssGreetTotals() {
      const section = document.getElementById('r_nssGreetSection');
      if (!section) return;
      let grand = 0;
      NSS_GREET_RUBRIC.forEach(s => {
        let sum = 0;
        s.items.forEach(it => {
          const el = section.querySelector('.mgr-nss-stars[data-nss-section-key="'+s.key+'"][data-nss-item-key="'+it.key+'"]');
          if (el) sum += parseInt(el.getAttribute('data-nss-value') || '0', 10);
        });
        grand += sum;
        const secEl = section.querySelector('[data-section-score="'+s.key+'"]');
        if (secEl) secEl.textContent = sum + ' / ' + s.max;
      });
      const grandEl = document.getElementById('r_nssGreetGrand');
      if (grandEl) grandEl.textContent = grand + ' / 100';
    }

    function mgrCollectNssGreetScores() {
      const section = document.getElementById('r_nssGreetSection');
      if (!section) return null;
      const out = { total: 0 };
      let any = false;
      NSS_GREET_RUBRIC.forEach(s => {
        out[s.key] = {};
        let sum = 0;
        s.items.forEach(it => {
          const el = section.querySelector('.mgr-nss-stars[data-nss-section-key="'+s.key+'"][data-nss-item-key="'+it.key+'"]');
          const v = el ? parseInt(el.getAttribute('data-nss-value') || '0', 10) : 0;
          out[s.key][it.key] = v;
          sum += v;
          if (v > 0) any = true;
        });
        out[s.key]._sum = sum;
        out.total += sum;
      });
      return any ? out : null;
    }

    function mgrAddCallRow() {
      const list = document.getElementById('r_callsList');
      const idx = list.children.length + 1;
      const div = document.createElement('div');
      div.className = 'mgr-call-item';
      div.innerHTML = `
        <span style="font-size:11px; font-weight:700; color:var(--text-muted); width:40px;">Call ${idx}</span>
        <input type="text" class="mgr-input" placeholder="Address / call type">
        <button type="button" class="mgr-call-remove" onclick="this.parentElement.remove()">&times;</button>
      `;
      list.appendChild(div);
    }

    function mgrUpdateRideSuggest() {
      const tech = document.getElementById('r_tech').value;
      const dp = skillsData.devPriorities[tech];
      const skillLookup = {};
      Object.keys(skillsData.categories).forEach(k => {
        skillsData.categories[k].skills.forEach(s => { skillLookup[s.id] = s.name; });
      });
      // combine devPriorities with missing NSS skills (rides often evaluate NSS)
      const missingNss = ['H1','H2','H3','H4','H5'].filter(id => !skillsData.assignments[tech].includes(id));
      const set = new Set();
      (dp?.next || []).forEach(id => set.add(String(id).split(' ')[0]));
      missingNss.forEach(id => set.add(id));
      const pills = Array.from(set).map(id => {
        const name = skillLookup[id];
        return `<span class="mgr-skill-pill">${id}${name?' — '+name:''}</span>`;
      }).join('');
      document.getElementById('r_suggestSkills').innerHTML = pills ?
        `<div class="mgr-suggested-skills">${pills}</div>` :
        `<div style="font-size:12px;color:var(--text-muted);">No gaps flagged</div>`;
    }

    function mgrSubmitRideAlong(ev, existingId, dateStr) {
      ev.preventDefault();
      const calls = Array.from(document.querySelectorAll('#r_callsList .mgr-call-item input')).map(i => i.value).filter(v => v.trim());
      const observations = {};
      document.querySelectorAll('#mgrRideAlongForm [data-obs]').forEach(cb => {
        observations[cb.dataset.obs] = cb.checked;
      });
      // Call Type — required
      var callTypeSel = document.querySelector('#mgrRideAlongForm input[name="r_callType"]:checked');
      var callType = callTypeSel ? callTypeSel.value : '';
      if (!callType) {
        alert('Please select a Call Type (Maintenance Call, Demand / Service Call, or Sold Work / Repair).');
        return false;
      }
      // Collect maintenance section data
      var maintenance = {};
      document.querySelectorAll('#mgrRideAlongForm [data-maint]').forEach(function(cb) {
        maintenance[cb.dataset.maint] = cb.checked;
      });
      var _mGet = function(id) { var el = document.getElementById(id); return el ? el.value : ''; };
      maintenance.inspectNotes = _mGet('r_maint_inspectNotes');
      maintenance.deltaT = _mGet('r_maint_deltaT');
      maintenance.pressures = _mGet('r_maint_pressures');
      maintenance.shsc = _mGet('r_maint_shsc');
      maintenance.amps = _mGet('r_maint_amps');
      maintenance.capReadings = _mGet('r_maint_capReadings');
      maintenance.staticPressure = _mGet('r_maint_static');
      maintenance.otherReadings = _mGet('r_maint_otherReadings');
      maintenance.recNotes = _mGet('r_maint_recNotes');
      maintenance.amount = _mGet('r_maint_amount');
      maintenance.leftWith = _mGet('r_maint_leftWith');
      // Collect demand section data
      var demand = {};
      document.querySelectorAll('#mgrRideAlongForm [data-demand]').forEach(function(cb) {
        demand[cb.dataset.demand] = cb.checked;
      });
      demand.symptom = _mGet('r_dem_symptom');
      demand.onset = _mGet('r_dem_onset');
      demand.history = _mGet('r_dem_history');
      demand.expectations = _mGet('r_dem_expectations');
      demand.diagSteps = _mGet('r_dem_diagSteps');
      demand.rootCause = _mGet('r_dem_rootCause');
      demand.contributing = _mGet('r_dem_contributing');
      demand.explained = _mGet('r_dem_explained');
      demand.options = _mGet('r_dem_options');
      demand.decision = _mGet('r_dem_decision');
      demand.postReadings = _mGet('r_dem_postReadings');
      demand.leftIn = _mGet('r_dem_leftIn');
      // Collect soldWork section data
      var soldWork = {};
      document.querySelectorAll('#mgrRideAlongForm [data-sold]').forEach(function(cb) {
        soldWork[cb.dataset.sold] = cb.checked;
      });
      soldWork.scope = _mGet('r_sold_scope');
      soldWork.soldBy = _mGet('r_sold_soldBy');
      soldWork.amount = _mGet('r_sold_amount');
      soldWork.history = _mGet('r_sold_history');
      soldWork.expectations = _mGet('r_sold_expectations');
      soldWork.baselineReadings = _mGet('r_sold_baselineReadings');
      soldWork.walkthrough = _mGet('r_sold_walkthrough');
      soldWork.issues = _mGet('r_sold_issues');
      soldWork.partsUsed = _mGet('r_sold_partsUsed');
      soldWork.laborHours = _mGet('r_sold_laborHours');
      soldWork.addlFindings = _mGet('r_sold_addlFindings');
      soldWork.addOns = _mGet('r_sold_addOns');
      soldWork.postReadings = _mGet('r_sold_postReadings');
      soldWork.satisfaction = _mGet('r_sold_satisfaction');
      soldWork.followUp = _mGet('r_sold_followUp');
      soldWork.leftIn = _mGet('r_sold_leftIn');
      // Reschedule: pull date/time/reason
      var rDateEl = document.getElementById('r_date');
      var rTimeEl = document.getElementById('r_time');
      var rReasonEl = document.getElementById('r_reason');
      var newRDate = (rDateEl && rDateEl.value) ? rDateEl.value : dateStr;
      var newRTime = (rTimeEl && rTimeEl.value) ? rTimeEl.value.trim() : '';
      var newRReason = (rReasonEl && rReasonEl.value) ? rReasonEl.value.trim() : '';
      const data = {
        callType,
        maintenance,
        demand,
        soldWork,
        ackObservation: document.getElementById('r_ackObs').checked,
        calls,
        custIssue: document.getElementById('r_custIssue').value,
        actualDiagnosis: document.getElementById('r_actualDiag').value,
        repairPerformed: document.getElementById('r_repairDone').value,
        callOutcome: document.getElementById('r_outcome').value,
        debriefManagerBetter: document.getElementById('r_mBetter').value,
        debriefTechBetter: document.getElementById('r_tBetter').value,
        debriefManagerWin: document.getElementById('r_mWin').value,
        debriefTechWin: document.getElementById('r_tWin').value,
        observations,
        observationNotes: document.getElementById('r_obsNotes').value,
        nextSteps: document.getElementById('r_nextSteps').value,
        nssGreetScores: mgrCollectNssGreetScores(),
        time: newRTime,
        rescheduleReason: newRReason
      };
      const status = document.querySelector('#mgrRideAlongForm input[name="r_status"]:checked').value;
      const tech = document.getElementById('r_tech').value;

      var isNew = !existingId;
      var rDateChanged = existingId && newRDate !== dateStr;
      if (existingId) {
        const idx = mgrState.entries.findIndex(e => e.id === existingId);
        if (idx >= 0) {
          mgrState.entries[idx] = { ...mgrState.entries[idx], tech, status, data, date: newRDate, time: newRTime, updatedAt: Date.now() };
        }
        // Update bulletin board entry if editing
        var bbRAEdit = bbLoad();
        var raIdx = bbRAEdit.rideAlongs.findIndex(function(r) { return r.id === existingId; });
        if (raIdx >= 0) {
          bbRAEdit.rideAlongs[raIdx].tech = tech;
          bbRAEdit.rideAlongs[raIdx].status = status;
          bbRAEdit.rideAlongs[raIdx].date = newRDate;
          bbRAEdit.rideAlongs[raIdx].time = newRTime;
          bbRAEdit.rideAlongs[raIdx].notes = data.observationNotes || '';
          bbSave(bbRAEdit);
        }
      } else {
        var newRAId = mgrUID();
        mgrState.entries.push({
          id: newRAId,
          type: 'ride-along',
          tech, date: newRDate, time: newRTime, status, data,
          createdAt: Date.now(), updatedAt: Date.now()
        });
      }
      mgrSave();
      renderManagerTab();
      renderBulletinBoard();
      mgrOpenDayPanel(newRDate);
      if (rDateChanged) {
        try {
          var rtoast = document.createElement('div');
          rtoast.textContent = '\u2705 Rescheduled ' + tech + ' Ride-Along \u2192 ' + newRDate;
          rtoast.style.cssText = 'position:fixed;bottom:30px;left:50%;transform:translateX(-50%);background:#065f46;color:#fff;padding:12px 24px;border-radius:10px;font-size:14px;font-weight:600;z-index:99999;box-shadow:0 4px 16px rgba(0,0,0,0.4);transition:opacity 0.4s;';
          document.body.appendChild(rtoast);
          setTimeout(function(){rtoast.style.opacity='0';},2200);
          setTimeout(function(){rtoast.remove();},2700);
        } catch(_) {}
      }

      // Show bulletin board prompt for new entries
      if (isNew) {
        _showBBPromptModal('ride-along', tech, dateStr, status, data.observationNotes || '', newRAId);
      }
      return false;
    }

    function mgrEditEntry(id) {
      const e = mgrState.entries.find(x => x.id === id);
      if (!e) return;
      mgrActiveDate = e.date;
      mgrStartForm(e.type, id);
    }

    function mgrDeleteEntry(id) {
      if (!confirm('Delete this entry? This cannot be undone.')) return;
      const e = mgrState.entries.find(x => x.id === id);
      const dateStr = e ? e.date : mgrActiveDate;
      mgrState.entries = mgrState.entries.filter(x => x.id !== id);
      mgrSave();
      // Also remove from bulletin board if synced
      var bb = bbLoad();
      var changed = false;
      if (e && e.type === 'one-on-one') {
        var before = bb.oneOnOnes.length;
        bb.oneOnOnes = bb.oneOnOnes.filter(function(o) { return o.id !== id; });
        if (bb.oneOnOnes.length < before) changed = true;
      } else if (e && e.type === 'ride-along') {
        var before2 = bb.rideAlongs.length;
        bb.rideAlongs = bb.rideAlongs.filter(function(r) { return r.id !== id; });
        if (bb.rideAlongs.length < before2) changed = true;
      }
      if (changed) { bbSave(bb); renderBulletinBoard(); }
      renderManagerTab();
      if (dateStr) mgrOpenDayPanel(dateStr);
    }

    // ----- Session Log -----
    function renderManagerLog() {
      // Populate filters
      const techSel = document.getElementById('mgrLogTech');
      const curTech = techSel.value;
      techSel.innerHTML = '<option value="">All Techs</option>' +
        Object.keys(skillsData.assignments).map(t => `<option value="${t}" ${t===curTech?'selected':''}>${t}</option>`).join('');

      const filtTech = document.getElementById('mgrLogTech').value;
      const filtType = document.getElementById('mgrLogType').value;
      const filtStatus = document.getElementById('mgrLogStatus').value;

      const filtered = mgrState.entries
        .filter(e => !filtTech || e.tech === filtTech)
        .filter(e => !filtType || e.type === filtType)
        .filter(e => !filtStatus || e.status === filtStatus)
        .sort((a, b) => (b.date || '').localeCompare(a.date || ''));

      if (!filtered.length) {
        document.getElementById('mgrLogTableWrap').innerHTML = `<div class="mgr-log-empty">No coaching entries yet. Click any day on the calendar to add one.</div>`;
        return;
      }

      // Check which entries are already on the bulletin board
      var bb = bbLoad();
      var bbOOIds = {};
      bb.oneOnOnes.forEach(function(o) { bbOOIds[o.id] = true; });
      var bbRAIds = {};
      bb.rideAlongs.forEach(function(r) { bbRAIds[r.id] = true; });

      let html = `<table class="mgr-log-table">
        <thead><tr>
          <th>Date</th><th>Type</th><th>Tech</th><th>Status</th><th>Summary</th><th class="mgr-only" style="width:40px;"></th>
        </tr></thead><tbody>`;
      filtered.forEach(e => {
        const d = mgrParseDate(e.date);
        const typeLabel = e.type === 'one-on-one' ? '1-on-1' : 'Ride-Along';
        const summary = e.data.coveredSummary || e.data.actualDiagnosis || e.data.debriefManagerBetter || e.data.customFocus || e.data.nextSteps || '—';
        const isOnBB = (e.type === 'one-on-one' && bbOOIds[e.id]) || (e.type === 'ride-along' && bbRAIds[e.id]);
        const bbBtn = isOnBB
          ? `<span title="On Bulletin Board" style="color:#4CAF50;font-size:16px;cursor:default;">\u2705</span>`
          : `<button class="mgr-bb-add-btn mgr-only" title="Add to Bulletin Board" onclick="event.stopPropagation(); _logAddToBB('${e.id}')" style="background:none;border:1px solid rgba(255,215,0,0.4);border-radius:6px;padding:3px 8px;font-size:11px;color:#fbbf24;cursor:pointer;white-space:nowrap;">+ BB</button>`;
        html += `<tr class="mgr-log-row" data-id="${e.id}">
          <td>${mgrFmtShort(d)} ${d.getFullYear()}</td>
          <td><span class="mgr-entry-type ${e.type}">${typeLabel}</span></td>
          <td><span class="mgr-log-tech-dot" style="background:${MGR_TECH_COLORS[e.tech]||'#888'}"></span>${e.tech}</td>
          <td><span class="mgr-entry-status ${e.status}">${e.status}</span></td>
          <td style="max-width:400px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${mgrEscape(summary.slice(0,140))}</td>
          <td class="mgr-only" style="text-align:center;">${bbBtn}</td>
        </tr>
        <tr class="mgr-log-detail" data-detail="${e.id}" style="display:none;"><td colspan="6" class="mgr-log-expanded">${mgrFormatEntryDetail(e)}</td></tr>`;
      });
      html += `</tbody></table>`;
      document.getElementById('mgrLogTableWrap').innerHTML = html;

      document.querySelectorAll('.mgr-log-row').forEach(row => {
        row.addEventListener('click', () => {
          const id = row.dataset.id;
          const detail = document.querySelector(`[data-detail="${id}"]`);
          if (detail) detail.style.display = detail.style.display === 'none' ? 'table-row' : 'none';
        });
      });
    }

    function _logAddToBB(entryId) {
      var entry = mgrState.entries.find(function(e) { return e.id === entryId; });
      if (!entry) { alert('Entry not found.'); return; }
      var notes = '';
      if (entry.type === 'one-on-one') {
        notes = entry.data.customFocus || entry.data.coveredSummary || '';
      } else {
        notes = entry.data.observationNotes || entry.data.debriefManagerBetter || '';
      }
      _showBBPromptModal(entry.type, entry.tech, entry.date, entry.status, notes, entry.id);
    }

    function mgrFormatEntryDetail(e) {
      const d = e.data || {};
      let html = '';
      if (e.type === 'one-on-one') {
        const hk = d.housekeeping || {};
        const hkDone = MGR_HOUSEKEEPING_ITEMS.filter(i => hk[i.key]).map(i => i.label).join(', ') || '—';
        html += `<h5>Housekeeping Complete</h5><div>${mgrEscape(hkDone)}</div>`;
        if (d.housekeepingNotes) html += `<div style="margin-top:4px;">Notes: ${mgrEscape(d.housekeepingNotes)}</div>`;
        if (d.customFocus) html += `<h5>Focus</h5><div>${mgrEscape(d.customFocus)}</div>`;
        if (d.redBarn?.include) html += `<h5>Red Barn</h5><div><strong>${mgrEscape(d.redBarn.scenario||'')}</strong> — ${mgrEscape(d.redBarn.outcome||'')}</div>`;
        if (d.coveredSummary) html += `<h5>Summary</h5><div>${mgrEscape(d.coveredSummary)}</div>`;
        if (d.actionItems) html += `<h5>Action Items</h5><div>${mgrEscape(d.actionItems)}</div>`;
        if (d.followUp) html += `<h5>Follow-up</h5><div>${mgrEscape(d.followUp)}</div>`;
      } else {
        if (d.calls?.length) html += `<h5>Calls Observed</h5><div>${d.calls.map(c => mgrEscape(c)).join(' · ')}</div>`;
        if (d.custIssue || d.actualDiagnosis || d.repairPerformed || d.callOutcome) {
          html += `<h5>Diagnostic Summary</h5>`;
          if (d.custIssue) html += `<div><strong>Customer issue:</strong> ${mgrEscape(d.custIssue)}</div>`;
          if (d.actualDiagnosis) html += `<div><strong>Actual diagnosis:</strong> ${mgrEscape(d.actualDiagnosis)}</div>`;
          if (d.repairPerformed) html += `<div><strong>Repair/options:</strong> ${mgrEscape(d.repairPerformed)}</div>`;
          if (d.callOutcome) html += `<div><strong>Outcome:</strong> ${mgrEscape(d.callOutcome)}</div>`;
        }
        const obs = d.observations || {};
        const obsDone = MGR_OBSERVATION_ITEMS.filter(i => obs[i.key]).map(i => i.label).join(', ') || '—';
        html += `<h5>Key Observations Seen</h5><div>${mgrEscape(obsDone)}</div>`;
        if (d.debriefManagerBetter) html += `<h5>Could be better (Manager)</h5><div>${mgrEscape(d.debriefManagerBetter)}</div>`;
        if (d.debriefTechBetter) html += `<h5>Could be better (Tech)</h5><div>${mgrEscape(d.debriefTechBetter)}</div>`;
        if (d.debriefManagerWin) html += `<h5>WIN (Manager view)</h5><div>${mgrEscape(d.debriefManagerWin)}</div>`;
        if (d.debriefTechWin) html += `<h5>WIN (Tech view)</h5><div>${mgrEscape(d.debriefTechWin)}</div>`;
        if (d.nextSteps) html += `<h5>Next Steps</h5><div>${mgrEscape(d.nextSteps)}</div>`;
        if (d.nssGreetScores && d.nssGreetScores.total) {
          const ng = d.nssGreetScores;
          const parts = NSS_GREET_RUBRIC.map(s => `${s.title}: <strong>${(ng[s.key]&&ng[s.key]._sum)||0}/${s.max}</strong>`).join(' · ');
          html += `<h5>NSS Greet Scorecard — ${ng.total}/100</h5><div style="font-size:11px;">${parts}</div>`;
        }
      }
      html += `<div style="margin-top:10px;"><button class="mgr-btn sm secondary" onclick="mgrEditEntry('${e.id}')">Edit</button> <button class="mgr-btn sm danger" onclick="mgrDeleteEntry('${e.id}')">Delete</button></div>`;
      return html;
    }

    // ----- Training Planner -----
    function renderManagerTraining() {
      const s = mgrGetSuggestedTraining();
      const covList = mgrGetCategoryCoverage().slice(0, 4);
      const skillLookup = {};
      Object.keys(skillsData.categories).forEach(k => {
        skillsData.categories[k].skills.forEach(sk => { skillLookup[sk.id] = sk.name; });
      });

      const suggestHtml = `
        <div class="mgr-suggest-topic">${mgrEscape(s.topic)}</div>
        <div class="mgr-suggest-rationale">${mgrEscape(s.rationale)}</div>
        <div style="margin:12px 0;">
          ${covList.map((c, i) => `<div class="mgr-suggest-stat"><strong>${c.name}</strong> — ${c.pct}% team coverage${i===0?' (lowest)':''}</div>`).join('')}
        </div>
        ${s.commonPriorities.length ? `<div style="font-size:12px; color:var(--text-muted); margin-bottom:6px;"><strong style="color:var(--text-primary);">Common dev priorities:</strong></div>
          <div class="mgr-suggested-skills">${s.commonPriorities.map(id => `<span class="mgr-skill-pill">${id}${skillLookup[id]?' — '+skillLookup[id]:''}</span>`).join('')}</div>` : ''}
        ${s.affectedTechs.length ? `<div style="font-size:12px; color:var(--text-muted); margin-top:10px;"><strong style="color:var(--text-primary);">Most affected:</strong> ${s.affectedTechs.join(', ')}</div>` : ''}
        <div style="margin-top:14px;">
          <button class="mgr-btn gold sm" onclick="mgrAdoptSuggestion()">Use this as this week's topic →</button>
        </div>
      `;
      document.getElementById('mgrSuggestBlock').innerHTML = suggestHtml;

      // Training builder
      if (!window._mgrTrainingWeekOf) {
        window._mgrTrainingWeekOf = mgrFmtDate(mgrStartOfWeek(mgrToday()));
      }
      const weekOf = window._mgrTrainingWeekOf;
      const existing = mgrState.trainings.find(t => t.weekOf === weekOf) || { weekOf, topic: '', outline: { duration: '30min', keyPoints: ['','',''], materials: '', redBarn: false, redBarnScenario: '' }, moment: { hook: '', example: '', takeaway: '' }, attendance: [] };

      const keyPoints = (existing.outline && existing.outline.keyPoints) ? existing.outline.keyPoints : ['','',''];
      const weekDate = mgrParseDate(weekOf);
      const weekEndDate = new Date(weekDate.getFullYear(), weekDate.getMonth(), weekDate.getDate() + 6);
      const weekLabel = mgrFmtShort(weekDate) + ' – ' + mgrFmtShort(weekEndDate) + ', ' + weekEndDate.getFullYear();
      const isCurrentWeek = weekOf === mgrFmtDate(mgrStartOfWeek(mgrToday()));

      document.getElementById('mgrTrainingBuilder').innerHTML = `
        <form id="mgrTrainingForm" onsubmit="return mgrSaveTraining(event);">
          <input type="hidden" id="t_weekOf" value="${weekOf}">
          <div class="mgr-form-row">
            <label class="mgr-form-label">Week of</label>
            <div class="mgr-week-nav">
              <button type="button" class="mgr-week-btn" onclick="mgrShiftTrainingWeek(-1)" title="Previous week">◀</button>
              <div class="mgr-week-display">
                <span class="mgr-week-label">${weekLabel}</span>
                ${isCurrentWeek ? '<span class="mgr-week-current">Current Week</span>' : ''}
              </div>
              <button type="button" class="mgr-week-btn" onclick="mgrShiftTrainingWeek(1)" title="Next week">▶</button>
              ${!isCurrentWeek ? '<button type="button" class="mgr-btn secondary sm" onclick="mgrResetTrainingWeek()" style="margin-left:8px;">Today</button>' : ''}
            </div>
          </div>
          <div class="mgr-form-row">
            <label class="mgr-form-label">Topic</label>
            <input type="text" class="mgr-input" id="t_topic" value="${mgrEscape(existing.topic||'')}" placeholder="e.g. Membership conversion deep-dive">
          </div>
          <div class="mgr-form-row">
            <label class="mgr-form-label">Why this topic (rationale)</label>
            <textarea class="mgr-textarea" id="t_rationale" rows="2">${mgrEscape(existing.rationale||'')}</textarea>
          </div>
          <div class="mgr-form-row">
            <label class="mgr-form-label">Duration</label>
            <select class="mgr-select" id="t_duration">
              <option value="15min" ${existing.outline?.duration==='15min'?'selected':''}>15 min</option>
              <option value="30min" ${existing.outline?.duration==='30min'?'selected':''}>30 min</option>
              <option value="45min" ${existing.outline?.duration==='45min'?'selected':''}>45 min</option>
              <option value="1hr" ${existing.outline?.duration==='1hr'?'selected':''}>1 hour</option>
              <option value="1.5hr" ${existing.outline?.duration==='1.5hr'?'selected':''}>1.5 hours</option>
              <option value="2hr" ${existing.outline?.duration==='2hr'?'selected':''}>2 hours</option>
              <option value="3hr" ${existing.outline?.duration==='3hr'?'selected':''}>3 hours</option>
              <option value="halfday" ${existing.outline?.duration==='halfday'?'selected':''}>Half day</option>
              <option value="fullday" ${existing.outline?.duration==='fullday'?'selected':''}>Full day</option>
              <option value="2days" ${existing.outline?.duration==='2days'?'selected':''}>2 days</option>
              <option value="3days" ${existing.outline?.duration==='3days'?'selected':''}>3 days</option>
              <option value="allweek" ${existing.outline?.duration==='allweek'?'selected':''}>All week</option>
            </select>
          </div>
          <div class="mgr-form-row">
            <label class="mgr-form-label">Key Points</label>
            <div id="t_keyPoints">
              ${keyPoints.map((p, i) => `
                <div class="mgr-keypoint-row">
                  <span class="mgr-keypoint-num">${i+1}.</span>
                  <input type="text" class="mgr-input" value="${mgrEscape(p)}">
                </div>
              `).join('')}
            </div>
            <button type="button" class="mgr-btn secondary sm" onclick="mgrAddKeyPoint()">+ Add key point</button>
          </div>
          <div class="mgr-form-row">
            <label class="mgr-form-label">Materials</label>
            <textarea class="mgr-textarea" id="t_materials" rows="2" placeholder="Handouts, slides, demos...">${mgrEscape(existing.outline?.materials||'')}</textarea>
          </div>
          <div class="mgr-form-row">
            <label class="mgr-check">
              <input type="checkbox" id="t_redBarn" ${existing.outline?.redBarn?'checked':''}>
              <span>Include Red Barn component</span>
            </label>
          </div>
          <div class="mgr-form-row">
            <label class="mgr-form-label">Red Barn Scenario (optional)</label>
            <input type="text" class="mgr-input" id="t_rbScenario" value="${mgrEscape(existing.outline?.redBarnScenario||'')}">
          </div>

          <div class="mgr-form-section">
            <div class="mgr-form-section-title">Impressionable Moment</div>
            <div class="mgr-form-row">
              <label class="mgr-form-label">Hook / Opener</label>
              <textarea class="mgr-textarea" id="t_hook" rows="2">${mgrEscape(existing.moment?.hook||'')}</textarea>
            </div>
            <div class="mgr-form-row">
              <label class="mgr-form-label">Real-world example</label>
              <textarea class="mgr-textarea" id="t_example" rows="2">${mgrEscape(existing.moment?.example||'')}</textarea>
            </div>
            <div class="mgr-form-row">
              <label class="mgr-form-label">Takeaway message</label>
              <textarea class="mgr-textarea" id="t_takeaway" rows="2">${mgrEscape(existing.moment?.takeaway||'')}</textarea>
            </div>
          </div>

          <div class="mgr-panel-actions" style="margin-top:12px;display:flex;flex-wrap:wrap;gap:8px;">
            <button type="submit" class="mgr-btn">Save Training Plan</button>
            <button type="button" class="mgr-btn secondary" onclick="mgrExportTrainingPDF()">Extract PDF</button>
            <button type="button" class="mgr-btn secondary" onclick="mgrTrainingAddToCalendar()" style="border-color:rgba(100,180,255,0.4);color:#64b4ff;">\ud83d\udcc5 Add to Calendar</button>
            <button type="button" class="mgr-btn secondary" onclick="mgrTrainingAddToBB()" style="border-color:rgba(255,215,0,0.4);color:#fbbf24;">\ud83d\udccc Add to Bulletin Board</button>
          </div>
        </form>
      `;

      // Past trainings
      const past = mgrState.trainings.slice().sort((a, b) => (b.weekOf || '').localeCompare(a.weekOf || ''));
      if (!past.length) {
        document.getElementById('mgrPastTrainings').innerHTML = `<div style="font-size:12px; color:var(--text-muted);">No trainings saved yet.</div>`;
      } else {
        document.getElementById('mgrPastTrainings').innerHTML = past.map(t => {
          var dur = (t.outline && t.outline.duration) ? t.outline.duration : '';
          var rb = (t.outline && t.outline.redBarn) ? ' · Red Barn' : '';
          var durLine = dur ? `<div style="font-size:11px; color:var(--text-muted); margin-top:2px;">${dur}${rb}</div>` : '';
          var isActive = t.weekOf === weekOf;
          // v213: surface attached PDFs from the Training Library (matched by weekOf)
          var attached = mgrLibraryAllItems().filter(function(L){ return L.weekOf === t.weekOf; });
          var attachedHtml = '';
          if (attached.length) {
            attachedHtml = '<div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:8px;" onclick="event.stopPropagation();">' +
              attached.map(function(L){
                return '<button type="button" class="mgr-btn secondary sm" onclick="event.stopPropagation();mgrLibraryView(\''+L.id+'\')" style="font-size:10px;padding:4px 8px;border-color:rgba(245,158,11,0.4);color:#fbbf24;">\ud83d\udcc4 ' + mgrEscape(L.title.replace(/^.*\u2014\s*/, '')) + '</button>';
              }).join('') +
              '</div>';
          }
          return `
          <div class="mgr-past-item${isActive ? ' mgr-past-active' : ''}" onclick="mgrLoadPastTraining('${t.weekOf}')" style="cursor:pointer;">
            <div class="mgr-past-item-date">Week of ${mgrFmtShort(mgrParseDate(t.weekOf))}, ${mgrParseDate(t.weekOf).getFullYear()} · ${(t.attendance||[]).length} attended</div>
            <div class="mgr-past-item-topic">${mgrEscape(t.topic || '(no topic)')}</div>
            ${durLine}
            ${attachedHtml}
            <div style="font-size:10px; color:var(--accent); margin-top:4px;">Tap to view &rarr;</div>
          </div>`;
        }).join('');
      }

      // Render Training Library
      mgrRenderTrainingLibrary();
    }

    function mgrAddKeyPoint() {
      const list = document.getElementById('t_keyPoints');
      const idx = list.children.length + 1;
      const div = document.createElement('div');
      div.className = 'mgr-keypoint-row';
      div.innerHTML = `<span class="mgr-keypoint-num">${idx}.</span><input type="text" class="mgr-input" value="">`;
      list.appendChild(div);
    }

    function mgrAdoptSuggestion() {
      const s = mgrGetSuggestedTraining();
      document.getElementById('t_topic').value = s.topic;
      document.getElementById('t_rationale').value = s.rationale;
    }

    function mgrShiftTrainingWeek(dir) {
      const current = mgrParseDate(window._mgrTrainingWeekOf);
      current.setDate(current.getDate() + (dir * 7));
      window._mgrTrainingWeekOf = mgrFmtDate(mgrStartOfWeek(current));
      renderManagerTraining();
    }

    function mgrResetTrainingWeek() {
      window._mgrTrainingWeekOf = mgrFmtDate(mgrStartOfWeek(mgrToday()));
      renderManagerTraining();
    }

    function mgrLoadPastTraining(weekOfStr) {
      window._mgrTrainingWeekOf = weekOfStr;
      renderManagerTraining();
      // Scroll to the training form at the top
      var builder = document.getElementById('mgrTrainingBuilder');
      if (builder) builder.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }

    function mgrSaveTraining(ev) {
      ev.preventDefault();
      const weekOf = document.getElementById('t_weekOf').value;
      const keyPoints = Array.from(document.querySelectorAll('#t_keyPoints input')).map(i => i.value);
      const outline = {
        duration: document.getElementById('t_duration').value,
        keyPoints,
        materials: document.getElementById('t_materials').value,
        redBarn: document.getElementById('t_redBarn').checked,
        redBarnScenario: document.getElementById('t_rbScenario').value
      };
      const moment = {
        hook: document.getElementById('t_hook').value,
        example: document.getElementById('t_example').value,
        takeaway: document.getElementById('t_takeaway').value
      };
      const topic = document.getElementById('t_topic').value;
      const rationale = document.getElementById('t_rationale').value;

      const idx = mgrState.trainings.findIndex(t => t.weekOf === weekOf);
      if (idx >= 0) {
        mgrState.trainings[idx] = { ...mgrState.trainings[idx], topic, rationale, outline, moment, updatedAt: Date.now() };
      } else {
        mgrState.trainings.push({
          id: mgrUID(),
          weekOf, topic, rationale, outline, moment,
          attendance: [], meetingNotes: '', meetingActions: '',
          createdAt: Date.now(), updatedAt: Date.now()
        });
      }
      mgrSave();
      renderManagerTraining();

      // Show calendar save modal
      var weekDate = mgrParseDate(weekOf);
      var wedDate = new Date(weekDate.getFullYear(), weekDate.getMonth(), weekDate.getDate() + 3); // Wednesday
      var wedStr = mgrFmtDate(wedDate);
      _showTrainingCalendarModal(topic, wedStr, outline.duration);
      return false;
    }

    // Standalone "Add to Calendar" for training plan (reads current form values)
    function mgrTrainingAddToCalendar() {
      var weekOf = document.getElementById('t_weekOf').value;
      var topic = document.getElementById('t_topic').value || '(No topic)';
      var duration = document.getElementById('t_duration').value || '';
      if (!weekOf) { alert('Please select a Week Of date first.'); return; }
      var weekDate = mgrParseDate(weekOf);
      var wedDate = new Date(weekDate.getFullYear(), weekDate.getMonth(), weekDate.getDate() + 3);
      var wedStr = mgrFmtDate(wedDate);

      var entryId = mgrUID();
      mgrState.entries.push({
        id: entryId, type: 'one-on-one', tech: 'Team', date: wedStr, status: 'planned',
        data: { housekeeping: {}, housekeepingNotes: '', customFocus: 'Wed HVAC Meeting: ' + topic + (duration ? ' (' + duration + ')' : ''), redBarn: { include: false, scenario: '', outcome: '' }, coveredSummary: '', actionItems: '', followUp: '' },
        createdAt: Date.now(), updatedAt: Date.now()
      });
      mgrSave();
      renderManagerCalendar();
      // Toast
      var toast = document.createElement('div');
      toast.textContent = '\u2705 Added to Calendar (' + wedStr + ')';
      toast.style.cssText = 'position:fixed;bottom:30px;left:50%;transform:translateX(-50%);background:#3b82f6;color:#fff;padding:12px 24px;border-radius:10px;font-size:14px;font-weight:600;z-index:99999;box-shadow:0 4px 16px rgba(0,0,0,0.4);transition:opacity 0.4s;';
      document.body.appendChild(toast);
      setTimeout(function() { toast.style.opacity = '0'; setTimeout(function() { toast.remove(); }, 400); }, 2000);
    }

    // Standalone "Add to Bulletin Board" for training plan
    function mgrTrainingAddToBB() {
      var weekOf = document.getElementById('t_weekOf').value;
      var topic = document.getElementById('t_topic').value || '(No topic)';
      var duration = document.getElementById('t_duration').value || '';
      if (!weekOf) { alert('Please select a Week Of date first.'); return; }
      var weekDate = mgrParseDate(weekOf);
      var wedDate = new Date(weekDate.getFullYear(), weekDate.getMonth(), weekDate.getDate() + 3);
      var wedStr = mgrFmtDate(wedDate);

      var bb = bbLoad();
      bb.meetings.push({
        id: bbUID(), subject: topic, date: wedStr, time: '', location: '', notes: duration ? 'Duration: ' + duration : '', source: 'mgr'
      });
      bbSave(bb);
      renderBulletinBoard();
      // Toast
      var toast = document.createElement('div');
      toast.textContent = '\u2705 Added to Bulletin Board';
      toast.style.cssText = 'position:fixed;bottom:30px;left:50%;transform:translateX(-50%);background:#065f46;color:#fff;padding:12px 24px;border-radius:10px;font-size:14px;font-weight:600;z-index:99999;box-shadow:0 4px 16px rgba(0,0,0,0.4);transition:opacity 0.4s;';
      document.body.appendChild(toast);
      setTimeout(function() { toast.style.opacity = '0'; setTimeout(function() { toast.remove(); }, 400); }, 2000);
    }

    // ========== TRAINING LIBRARY ==========
    function mgrLibraryAllItems() {
      var userItems = Array.isArray(mgrState.library) ? mgrState.library : [];
      // Seeds first, then user-added (most recent first)
      var seeds = TRAINING_LIBRARY_SEED.slice();
      var user = userItems.slice().sort(function(a,b){ return (b.createdAt||0) - (a.createdAt||0); });
      return seeds.concat(user);
    }

    function mgrRenderTrainingLibrary() {
      var container = document.getElementById('mgrTrainingLibrary');
      if (!container) return;
      var items = mgrLibraryAllItems();
      if (!items.length) {
        container.innerHTML = '<div style="font-size:12px;color:var(--text-muted);">No trainings in library yet. Click + Add Training to save one.</div>';
        return;
      }
      container.innerHTML = '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:12px;">' +
        items.map(function(it){
          var tags = (it.tags||[]).map(function(t){ return '<span style="display:inline-block;background:rgba(255,215,0,0.12);color:#fbbf24;font-size:10px;padding:2px 7px;border-radius:10px;margin-right:4px;">'+mgrEscape(t)+'</span>'; }).join('');
          var dur = it.duration ? '<span style="font-size:11px;color:var(--text-muted);">'+mgrEscape(it.duration)+'</span>' : '';
          var builtinBadge = it.builtin ? '<span style="display:inline-block;background:rgba(100,180,255,0.15);color:#64b4ff;font-size:9px;padding:1px 6px;border-radius:8px;margin-left:6px;letter-spacing:0.5px;">BUILT-IN</span>' : '';
          var deleteBtn = it.builtin ? '' :
            '<button type="button" class="mgr-btn secondary sm" onclick="mgrLibraryDelete(\''+it.id+'\')" style="border-color:rgba(255,100,100,0.4);color:#f87171;">🗑 Delete</button>';

          // Category color chip (uses categoryKey if available, falls back to label-based color)
          var catMeta = it.categoryKey ? mgrLibraryCategoryByKey(it.categoryKey) : null;
          var catColor = (catMeta && catMeta.color) || it.categoryColor || '#a3a3a3';
          var catLabel = (catMeta && catMeta.label) || it.category || '';
          var catChip = catLabel
            ? '<span style="display:inline-block;background:'+catColor+'22;color:'+catColor+';border:1px solid '+catColor+'44;font-size:10px;font-weight:700;padding:2px 8px;border-radius:6px;letter-spacing:0.3px;">'+mgrEscape(catLabel)+'</span>'
            : '';

          // "Uploaded by" + date metadata footer
          var metaParts = [];
          if (it.uploadedBy) metaParts.push('👤 '+mgrEscape(it.uploadedBy));
          if (it.uploadedAt) metaParts.push(mgrLibraryFmtDate(it.uploadedAt));
          else if (it.createdAt && !it.builtin) metaParts.push(mgrLibraryFmtDate(it.createdAt));
          var metaFooter = metaParts.length
            ? '<div style="font-size:10px;color:var(--text-muted);margin-top:4px;border-top:1px dashed rgba(255,255,255,0.08);padding-top:6px;">'+metaParts.join(' · ')+'</div>'
            : '';

          // File source indicator (☁ Drive uploaded vs 🔗 external link vs builtin)
          var sourceIcon = '';
          if (it.builtin) sourceIcon = '';
          else if (it.hasFile) sourceIcon = '<span title="Uploaded to Drive — syncs across devices" style="font-size:10px;color:#34d399;margin-left:6px;">☁ Drive</span>';
          else if (it.pdf) sourceIcon = '<span title="External link" style="font-size:10px;color:#94a3b8;margin-left:6px;">🔗 Link</span>';

          return '' +
            '<div style="background:rgba(0,0,0,0.25);border:1px solid var(--border);border-left:3px solid '+catColor+';border-radius:10px;padding:14px;display:flex;flex-direction:column;gap:8px;">' +
              '<div>' +
                '<div style="display:flex;align-items:center;flex-wrap:wrap;gap:6px;margin-bottom:5px;">'+catChip+sourceIcon+builtinBadge+'</div>' +
                '<div style="font-weight:700;font-size:14px;color:var(--text-primary);line-height:1.3;">'+mgrEscape(it.title)+'</div>' +
              '</div>' +
              (it.description ? '<div style="font-size:12px;color:var(--text-muted);line-height:1.4;">'+mgrEscape(it.description)+'</div>' : '') +
              (tags || dur ? '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;">'+tags+dur+'</div>' : '') +
              '<div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:4px;">' +
                '<button type="button" class="mgr-btn sm" onclick="mgrLibraryView(\''+it.id+'\')">👁 View</button>' +
                '<button type="button" class="mgr-btn secondary sm" onclick="mgrLibraryDownload(\''+it.id+'\')">⬇ Download</button>' +
                '<button type="button" class="mgr-btn secondary sm" onclick="mgrLibraryAddToCalendar(\''+it.id+'\')" style="border-color:rgba(100,180,255,0.4);color:#64b4ff;">📅 Calendar</button>' +
                '<button type="button" class="mgr-btn secondary sm" onclick="mgrLibraryAddToBB(\''+it.id+'\')" style="border-color:rgba(255,215,0,0.4);color:#fbbf24;">📌 Bulletin</button>' +
                deleteBtn +
              '</div>' +
              metaFooter +
            '</div>';
        }).join('') + '</div>';
    }

    function mgrLibraryFind(id) {
      return mgrLibraryAllItems().find(function(x){ return x.id === id; });
    }

    function mgrLibraryToast(msg, color) {
      var toast = document.createElement('div');
      toast.textContent = msg;
      toast.style.cssText = 'position:fixed;bottom:30px;left:50%;transform:translateX(-50%);background:'+(color||'#3b82f6')+';color:#fff;padding:12px 24px;border-radius:10px;font-size:14px;font-weight:600;z-index:99999;box-shadow:0 4px 16px rgba(0,0,0,0.4);transition:opacity 0.4s;';
      document.body.appendChild(toast);
      setTimeout(function(){ toast.style.opacity='0'; setTimeout(function(){ toast.remove(); }, 400); }, 2000);
    }

    // Get a usable URL/dataURL for an uploaded library file. Tries:
    //   1. localStorage (instant, only on the device that uploaded)
    //   2. Drive via tfDriveMap (works across devices)
    // Returns a Promise resolving to a data URL or string href, or null.
    async function mgrLibraryResolveUploadedFile(it) {
      if (!it) return null;
      // 1. Local cache
      try {
        var local = localStorage.getItem('snappy_lib_localfile_' + it.id);
        if (local) return local;
      } catch (e) {}
      // 2. Drive map (shared across all devices once Drive upload completes)
      try {
        if (typeof tfDriveMap !== 'undefined' && tfDriveMap[it.id]) {
          var data = await _tfFetchFromDrive(tfDriveMap[it.id]);
          if (data) {
            try { localStorage.setItem('snappy_lib_localfile_' + it.id, data); } catch (e) {}
            return data;
          }
        }
      } catch (e) { console.warn('Drive fetch for library file failed:', e); }
      return null;
    }

    async function mgrLibraryView(id) {
      var it = mgrLibraryFind(id);
      if (!it) return;
      // 1. Direct uploaded file → resolve from local cache or Drive
      if (it.hasFile) {
        mgrLibraryToast('☁ Loading file…', '#1e40af');
        var dataUrl = await mgrLibraryResolveUploadedFile(it);
        if (!dataUrl) {
          alert('Could not load this file. It may still be syncing to Drive — try again in a few seconds, or refresh the page.');
          return;
        }
        // Show in viewer modal using the data URL
        _mgrLibraryOpenViewer({ pdf: dataUrl, title: it.title });
        return;
      }
      // 2. External link / built-in PDF base64 lookup
      if (!it.pdf) { alert('No file attached to this training.'); return; }
      if (typeof PDF_BASE64 !== 'undefined' && PDF_BASE64[it.pdf]) {
        try { openEmbeddedPDF(it.pdf); return; } catch (e) { /* fall through */ }
      }
      _mgrLibraryOpenViewer(it);
    }

    function _mgrLibraryOpenViewer(it) {
      var old = document.getElementById('mgrLibraryViewerModal');
      if (old) old.remove();
      var modal = document.createElement('div');
      modal.id = 'mgrLibraryViewerModal';
      modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.92);z-index:99999;display:flex;flex-direction:column;';
      var safePdf = String(it.pdf).replace(/"/g,'&quot;');
      var safeTitle = mgrEscape(it.title || 'Training');
      modal.innerHTML = '' +
        '<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 14px;background:#111;border-bottom:1px solid var(--border);flex-shrink:0;">' +
          '<div style="font-weight:700;font-size:14px;color:#fff;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + safeTitle + '</div>' +
          '<div style="display:flex;gap:6px;flex-shrink:0;">' +
            '<a href="' + safePdf + '" target="_blank" rel="noopener" class="mgr-btn secondary sm" style="text-decoration:none;">↗ New Tab</a>' +
            '<button type="button" class="mgr-btn secondary sm" onclick="_mgrLibraryCloseViewer()" style="border-color:rgba(255,100,100,0.5);color:#f87171;">✕ Close</button>' +
          '</div>' +
        '</div>' +
        '<div style="flex:1;overflow:hidden;background:#222;">' +
          '<iframe src="' + safePdf + '" style="width:100%;height:100%;border:0;" title="' + safeTitle + '"></iframe>' +
        '</div>';
      document.body.appendChild(modal);
      // ESC to close
      document.addEventListener('keydown', _mgrLibraryViewerKeyHandler);
    }

    function _mgrLibraryCloseViewer() {
      var modal = document.getElementById('mgrLibraryViewerModal');
      if (modal) modal.remove();
      document.removeEventListener('keydown', _mgrLibraryViewerKeyHandler);
    }

    function _mgrLibraryViewerKeyHandler(e) {
      if (e.key === 'Escape') _mgrLibraryCloseViewer();
    }

    async function mgrLibraryDownload(id) {
      var it = mgrLibraryFind(id);
      if (!it) return;
      var href = '';
      var fileName = '';

      if (it.hasFile) {
        // Resolve uploaded file from cache or Drive
        mgrLibraryToast('☁ Preparing download…', '#1e40af');
        var dataUrl = await mgrLibraryResolveUploadedFile(it);
        if (!dataUrl) { alert('Could not load this file. It may still be syncing to Drive — try again shortly.'); return; }
        href = dataUrl;
        fileName = it.fileName || (it.title ? (it.title + '.pdf') : 'download.pdf');
      } else if (it.pdf) {
        if (typeof PDF_BASE64 !== 'undefined' && PDF_BASE64[it.pdf]) {
          href = 'data:application/pdf;base64,' + PDF_BASE64[it.pdf];
          fileName = (it.title || 'download') + '.pdf';
        } else {
          href = it.pdf;
          fileName = it.pdf.split('/').pop().split('?')[0] || 'download';
        }
      } else {
        alert('No file attached to this training.');
        return;
      }

      var a = document.createElement('a');
      a.href = href;
      a.download = fileName;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    }

    function mgrLibraryDelete(id) {
      var it = mgrLibraryFind(id);
      if (!it) return;
      if (it.builtin) { alert('Built-in trainings cannot be deleted.'); return; }
      if (!confirm('Delete "'+it.title+'" from the library?')) return;
      mgrState.library = mgrState.library.filter(function(x){ return x.id !== id; });
      mgrSave();
      mgrRenderTrainingLibrary();
      mgrLibraryToast('🗑 Deleted', '#7f1d1d');
    }

    function mgrLibraryAddToCalendar(id) {
      var it = mgrLibraryFind(id);
      if (!it) return;
      var today = mgrToday();
      var weekStart = mgrStartOfWeek(today);
      var wedDate = new Date(weekStart.getFullYear(), weekStart.getMonth(), weekStart.getDate() + 3);
      // If Wed already passed this week, schedule next week's Wed
      if (wedDate < today) {
        wedDate.setDate(wedDate.getDate() + 7);
      }
      var wedStr = mgrFmtDate(wedDate);
      var focusLabel = 'Training: ' + it.title + (it.duration ? ' (' + it.duration + ')' : '');
      mgrState.entries.push({
        id: mgrUID(), type: 'one-on-one', tech: 'Team', date: wedStr, status: 'planned',
        data: { housekeeping: {}, housekeepingNotes: '', customFocus: focusLabel, redBarn: { include: false, scenario: '', outcome: '' }, coveredSummary: '', actionItems: '', followUp: '' },
        createdAt: Date.now(), updatedAt: Date.now()
      });
      mgrSave();
      if (typeof renderManagerCalendar === 'function') renderManagerCalendar();
      mgrLibraryToast('📅 Added to Calendar (' + wedStr + ')', '#3b82f6');
    }

    function mgrLibraryAddToBB(id) {
      var it = mgrLibraryFind(id);
      if (!it) return;
      var today = mgrToday();
      var weekStart = mgrStartOfWeek(today);
      var wedDate = new Date(weekStart.getFullYear(), weekStart.getMonth(), weekStart.getDate() + 3);
      if (wedDate < today) { wedDate.setDate(wedDate.getDate() + 7); }
      var wedStr = mgrFmtDate(wedDate);
      var notes = (it.description || '') + (it.duration ? (it.description ? ' · ' : '') + 'Duration: ' + it.duration : '');
      var bb = bbLoad();
      bb.meetings.push({
        id: bbUID(), subject: 'Training: ' + it.title, date: wedStr, time: '', location: '', notes: notes, source: 'mgr'
      });
      bbSave(bb);
      if (typeof renderBulletinBoard === 'function') renderBulletinBoard();
      mgrLibraryToast('📌 Posted to Bulletin Board', '#065f46');
    }

    // Standard training categories — color-coded for visual scanning
    var LIBRARY_CATEGORIES = [
      { key: 'refrigeration', label: 'Refrigeration',      color: '#60a5fa' },
      { key: 'electrical',    label: 'Electrical',         color: '#fbbf24' },
      { key: 'airflow',       label: 'Airflow',            color: '#34d399' },
      { key: 'heating',       label: 'Heating',            color: '#f87171' },
      { key: 'cooling',       label: 'Cooling',            color: '#22d3ee' },
      { key: 'install',       label: 'Install',            color: '#a78bfa' },
      { key: 'diagnostics',   label: 'Diagnostics',        color: '#fb923c' },
      { key: 'customer',      label: 'Customer / NSS',     color: '#f472b6' },
      { key: 'sales',         label: 'Sales / SPP',        color: '#facc15' },
      { key: 'safety',        label: 'Safety',             color: '#ef4444' },
      { key: 'professionalism', label: 'Professionalism',  color: '#94a3b8' },
      { key: 'leadership',    label: 'Leadership',         color: '#c084fc' },
      { key: 'other',         label: 'Other',              color: '#64748b' }
    ];
    function mgrLibraryCategoryByKey(k) {
      for (var i = 0; i < LIBRARY_CATEGORIES.length; i++) {
        if (LIBRARY_CATEGORIES[i].key === k) return LIBRARY_CATEGORIES[i];
      }
      return null;
    }
    // Auto-suggest category from title/description text (best-effort)
    function mgrLibraryAutoCategory(text) {
      if (!text) return '';
      var t = String(text).toLowerCase();
      var rules = [
        ['refrigeration', /refriger|superheat|subcool|saturation|txv|piston|metering|charge|r-?410|r-?22|r-?32/],
        ['electrical',   /electric|voltage|capacitor|contactor|ohm|amp|circuit|fuse|relay|wiring|schematic/],
        ['airflow',      /airflow|static.?press|duct|cfm|blower|filter|return|supply.?air/],
        ['heating',      /furnace|heat.?exchanger|gas.?valve|flue|ignit|burner|combustion|heating/],
        ['cooling',      /cool|condenser|evap.?coil|a\/?c\b|air.?cond/],
        ['install',      /install|change.?out|replacement|line.?set|braz|vacuum|nitrog/],
        ['diagnostics',  /diagnos|troubleshoot|callback|fault|symptom|a\/b\/c.?chart/],
        ['customer',     /nss|greet|customer|communic|present|wow|review|five.?star|home.?advisor/],
        ['sales',        /sales|spp|service.?partner|membership|club|club.?member|tgl|conversion|closing/],
        ['safety',       /safety|ppe|ladder|lockout|tagout|harness|fall.?protect/],
        ['professionalism', /uniform|grooming|appear|professional|odor/],
        ['leadership',   /leader|coaching|huddle|1.?on.?1|ride.?along|team.?build/]
      ];
      for (var i = 0; i < rules.length; i++) {
        if (rules[i][1].test(t)) return rules[i][0];
      }
      return '';
    }
    // Resolve who is currently "uploading" — prefer Manager > Editor > Coach > Anonymous
    function mgrLibraryWhoAmI() {
      try {
        if (typeof isManagerMode !== 'undefined' && isManagerMode) return 'Mark Sanders';
        if (typeof isEditorMode  !== 'undefined' && isEditorMode  && editorName) return editorName;
        if (typeof isCoachMode   !== 'undefined' && isCoachMode   && coachName)  return coachName;
      } catch (e) {}
      return 'Team';
    }
    // Format a friendly date label (e.g. "Apr 24, 2026")
    function mgrLibraryFmtDate(ts) {
      try {
        if (!ts) return '';
        var d = new Date(ts);
        var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
        return months[d.getMonth()] + ' ' + d.getDate() + ', ' + d.getFullYear();
      } catch (e) { return ''; }
    }

    // Read a File object as a base64 data URL
    function mgrLibraryReadFile(file) {
      return new Promise(function(resolve, reject) {
        var reader = new FileReader();
        reader.onload  = function() { resolve(reader.result); };
        reader.onerror = function() { reject(new Error('File read error')); };
        reader.readAsDataURL(file);
      });
    }
    // Upload an uploaded library file to Drive (reuses Tech Files Drive infrastructure).
    // Returns the driveFileId (best-effort — fire-and-forget on no-cors).
    function mgrLibraryUploadToDrive(entryId, fileName, fileDataUrl) {
      try {
        if (!SyncEngine.isConfigured() || !fileDataUrl) return;
        var payload = JSON.stringify({
          _action: 'uploadFile',
          techName: 'Library',           // routes into the same Drive folder, prefixed "Library_"
          fileEntryId: entryId,          // shared drive map keyed by entry id
          fileName: fileName,
          fileData: fileDataUrl
        });
        fetch(SYNC_URL, {
          method: 'POST',
          mode: 'no-cors',
          headers: { 'Content-Type': 'text/plain' },
          body: payload
        }).catch(function(err) { console.warn('Library Drive upload failed:', err); });
      } catch (e) { console.warn('Library Drive upload error:', e); }
    }

    function mgrLibraryOpenAddModal() {
      var old = document.getElementById('mgrLibraryAddModal');
      if (old) old.remove();
      var modal = document.createElement('div');
      modal.id = 'mgrLibraryAddModal';
      modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.7);z-index:99998;display:flex;align-items:center;justify-content:center;padding:20px;';
      var catOpts = LIBRARY_CATEGORIES.map(function(c){
        return '<option value="'+c.key+'" data-color="'+c.color+'">'+c.label+'</option>';
      }).join('');
      modal.innerHTML = '' +
        '<div style="background:var(--panel-bg,#1a1a1a);border:1px solid var(--border);border-radius:14px;padding:22px;max-width:520px;width:100%;max-height:90vh;overflow-y:auto;box-shadow:0 10px 40px rgba(0,0,0,0.6);">' +
          '<h3 style="margin:0 0 4px 0;color:var(--text-primary);">Add Training to Library</h3>' +
          '<div style="font-size:11px;color:var(--text-muted);margin-bottom:14px;">Uploads sync across all devices via Google Drive.</div>' +
          '<form id="mgrLibraryAddForm" onsubmit="return mgrLibraryAddSubmit(event);">' +
            '<div class="mgr-form-row"><label class="mgr-form-label">Title *</label><input type="text" class="mgr-input" id="lib_title" required placeholder="e.g. Refrigeration Cycle Fundamentals" oninput="mgrLibrarySuggestCategory()"></div>' +
            '<div class="mgr-form-row"><label class="mgr-form-label">Category *</label>' +
              '<select class="mgr-select" id="lib_category_key" required>' +
                '<option value="">— Select a category —</option>' + catOpts +
              '</select>' +
              '<div id="lib_category_hint" style="font-size:10px;color:var(--text-muted);margin-top:4px;display:none;">💡 Auto-suggested from title — change if needed.</div>' +
            '</div>' +
            '<div class="mgr-form-row"><label class="mgr-form-label">Description</label><textarea class="mgr-textarea" id="lib_description" rows="2" placeholder="Short summary" oninput="mgrLibrarySuggestCategory()"></textarea></div>' +
            '<div class="mgr-form-row"><label class="mgr-form-label">📎 Upload PDF (optional)</label>' +
              '<input type="file" id="lib_file" accept="application/pdf,image/*" class="mgr-input" style="padding:6px;">' +
              '<div style="font-size:10px;color:var(--text-muted);margin-top:4px;">Pick a file from this device. It uploads to Google Drive so the team can view it from any device.</div>' +
            '</div>' +
            '<div style="text-align:center;font-size:10px;color:var(--text-muted);margin:8px 0;">— OR —</div>' +
            '<div class="mgr-form-row"><label class="mgr-form-label">Paste a Link</label><input type="text" class="mgr-input" id="lib_pdf" placeholder="https://drive.google.com/... or Dropbox link"><div style="font-size:10px;color:var(--text-muted);margin-top:4px;">Use this if the file already lives on Drive / Dropbox / SharePoint.</div></div>' +
            '<div class="mgr-form-row"><label class="mgr-form-label">Duration</label>' +
              '<select class="mgr-select" id="lib_duration">' +
                '<option value="">—</option>' +
                '<option value="15min">15 min</option><option value="30min">30 min</option><option value="45min">45 min</option>' +
                '<option value="1hr" selected>1 hour</option><option value="1.5hr">1.5 hours</option><option value="2hr">2 hours</option>' +
                '<option value="3hr">3 hours</option><option value="halfday">Half day</option><option value="fullday">Full day</option>' +
              '</select></div>' +
            '<div class="mgr-form-row"><label class="mgr-form-label">Tags (comma-separated)</label><input type="text" class="mgr-input" id="lib_tags" placeholder="NSS, Greet, Instructor"></div>' +
            '<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:14px;">' +
              '<button type="button" class="mgr-btn secondary" onclick="document.getElementById(\'mgrLibraryAddModal\').remove()">Cancel</button>' +
              '<button type="submit" class="mgr-btn gold" id="lib_submit_btn">Save to Library</button>' +
            '</div>' +
          '</form>' +
        '</div>';
      document.body.appendChild(modal);
      setTimeout(function(){ var t = document.getElementById('lib_title'); if (t) t.focus(); }, 50);
    }
    // Live category suggestion based on Title + Description text
    function mgrLibrarySuggestCategory() {
      try {
        var sel = document.getElementById('lib_category_key');
        if (!sel || sel.value) return; // don't override a manual choice
        var title = (document.getElementById('lib_title')||{}).value || '';
        var desc  = (document.getElementById('lib_description')||{}).value || '';
        var key = mgrLibraryAutoCategory(title + ' ' + desc);
        if (key) {
          sel.value = key;
          var hint = document.getElementById('lib_category_hint');
          if (hint) hint.style.display = 'block';
        }
      } catch (e) {}
    }
    window.mgrLibrarySuggestCategory = mgrLibrarySuggestCategory;

    async function mgrLibraryAddSubmit(ev) {
      ev.preventDefault();
      var title = document.getElementById('lib_title').value.trim();
      if (!title) { alert('Title is required.'); return false; }
      var categoryKey = document.getElementById('lib_category_key').value;
      if (!categoryKey) { alert('Please choose a category.'); return false; }
      var fileEl = document.getElementById('lib_file');
      var pickedFile = fileEl && fileEl.files && fileEl.files[0] ? fileEl.files[0] : null;
      var pastedUrl  = document.getElementById('lib_pdf').value.trim();
      if (!pickedFile && !pastedUrl) {
        if (!confirm('No file or link attached. Save the entry anyway?')) return false;
      }

      var submitBtn = document.getElementById('lib_submit_btn');
      var origLabel = submitBtn ? submitBtn.textContent : '';
      if (submitBtn) { submitBtn.disabled = true; submitBtn.textContent = pickedFile ? 'Uploading…' : 'Saving…'; }

      var tagsRaw = document.getElementById('lib_tags').value.trim();
      var tags = tagsRaw ? tagsRaw.split(',').map(function(s){ return s.trim(); }).filter(Boolean) : [];
      var catMeta = mgrLibraryCategoryByKey(categoryKey);
      var entryId = 'lib_' + mgrUID();

      var entry = {
        id: entryId,
        title: title,
        categoryKey: categoryKey,
        category: catMeta ? catMeta.label : '',          // back-compat (old field used by rendering)
        categoryColor: catMeta ? catMeta.color : '#64748b',
        description: document.getElementById('lib_description').value.trim(),
        pdf: pastedUrl,                                  // external link (if any)
        fileName: pickedFile ? pickedFile.name : '',
        fileSize: pickedFile ? pickedFile.size : 0,
        hasFile: !!pickedFile,                           // true if uploaded directly
        duration: document.getElementById('lib_duration').value,
        tags: tags,
        builtin: false,
        uploadedBy: mgrLibraryWhoAmI(),
        uploadedAt: Date.now(),
        createdAt: Date.now()
      };

      // If a file was picked, read as base64 and upload to Drive (cross-device).
      if (pickedFile) {
        try {
          var dataUrl = await mgrLibraryReadFile(pickedFile);
          // Stash locally so author can view immediately even before Drive responds
          try {
            var localKey = 'snappy_lib_localfile_' + entryId;
            localStorage.setItem(localKey, dataUrl);
          } catch (e) { /* quota — fine, Drive copy still works */ }
          // Fire upload to Drive (background)
          mgrLibraryUploadToDrive(entryId, pickedFile.name, dataUrl);
        } catch (e) {
          alert('Could not read the file: ' + e.message);
          if (submitBtn) { submitBtn.disabled = false; submitBtn.textContent = origLabel; }
          return false;
        }
      }

      if (!Array.isArray(mgrState.library)) mgrState.library = [];
      mgrState.library.push(entry);
      mgrSave();
      var modal = document.getElementById('mgrLibraryAddModal');
      if (modal) modal.remove();
      mgrRenderTrainingLibrary();
      mgrLibraryToast(pickedFile ? '☁ Uploaded & saved — syncing to team' : '✅ Added to Library', '#065f46');
      return false;
    }

    // Expose library functions
    window.mgrLibraryView = mgrLibraryView;
    window.mgrLibraryDownload = mgrLibraryDownload;
    window.mgrLibraryDelete = mgrLibraryDelete;
    window.mgrLibraryAddToCalendar = mgrLibraryAddToCalendar;
    window.mgrLibraryAddToBB = mgrLibraryAddToBB;
    window.mgrLibraryOpenAddModal = mgrLibraryOpenAddModal;
    window.mgrLibraryAddSubmit = mgrLibraryAddSubmit;
    window._mgrLibraryCloseViewer = _mgrLibraryCloseViewer;

